INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (1,'bwindi-impenetrable-national-park','Bwindi Impenetrable National Park','Bwindi','Half the world''s mountain gorillas in one ancient forest',3,'Kanungu, Kisoro, Kabale & Rubanda','South-western Uganda, on the edge of the Albertine Rift',-1.0586,29.6749,'https://sspark.genspark.ai/i/I4JvByiZFsBH6sa5?width=2560','https://sspark.genspark.ai/i/AxfRnLrLz2AyPCES?width=2560','A 321 km² block of Afromontane rainforest holding roughly half of all surviving mountain gorillas — and the single reason most visitors come to Uganda.','Bwindi is old. Pollen records suggest the forest has stood here for more than 25,000 years, surviving the ice ages that stripped most of East Africa''s highland forest. That continuity is why it is so dense and so biologically rich: over 1,000 flowering plant species, 350 birds, 200 butterflies and around 400 mountain gorillas — close to half the global population of roughly 1,060.
INSERT INTO destination_categories (destination_id,category_id) VALUES (1,1);
