INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (1,'gorilla-trekking','Gorilla Trekking','fa-hippo','The headline experience. You meet at the sector briefing point at 07:30, are assigned to a gorilla family in a group of no more than eight, and walk into the forest with armed rangers and trackers who have been locating the group since dawn. Walking time varies from 30 minutes to seven hours. Once you reach the family you get exactly one hour with them at a nominal seven-metre distance, though the gorillas themselves frequently ignore that rule.','2–8 hours total','challenging',800,800,3000000,3000000,'USD 800 per permit for foreign non-residents; USD 700 for foreign residents; UGX 300,000 for East African citizens. Permit must be booked in advance through UWA or a licensed operator.','15 years and above — strictly enforced','["Hiking boots","Rain jacket","Gloves","Water","Packed lunch","Camera without flash"]','All year; easier walking Jun–Aug and Dec–Feb','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (1,'gorilla-habituation','Gorilla Habituation Experience','fa-clock','Available only in the Rushaga sector. Instead of one hour you spend four hours with a semi-habituated family alongside the researchers and trackers who are conditioning them to human presence. Group size is capped at four visitors. It is a substantially deeper experience than standard trekking and correspondingly more demanding, since you follow the group as it moves and feeds rather than arriving at a located position.','6–10 hours','expert',1500,1500,5625000,5625000,'USD 1,500 per person for foreign non-residents. Only four permits per day.','15 years and above','["Full hiking kit","Two litres of water","Substantial packed lunch","Waterproofs","Gaiters"]','Jun–Aug and Dec–Feb strongly recommended','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (1,'batwa-cultural-trail','Batwa Cultural Experience','fa-drum','The Batwa lived as hunter-gatherers in this forest until the park was gazetted in 1991 and they were evicted. Batwa guides walk you through the forest edge demonstrating hunting techniques, medicinal plants, fire-making and traditional shelter construction, and the day usually closes with music and dance at a community settlement. It is a direct and sometimes uncomfortable account of conservation''s human cost, and the fees go to the community.','3–4 hours','easy',40,80,150000,300000,'USD 40–80 per person depending on the community group and sector.','All ages','["Walking shoes","Sun hat","Cash for crafts"]','All year','culture',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (1,'bwindi-birding','Albertine Rift Birding','fa-dove','Bwindi records around 350 species including 23 of the 24 Albertine Rift endemics. The Ruhija sector and the Mubwindi Swamp trail are the productive areas, and the swamp is the classic site for African green broadbill and Grauer''s rush warbler. Serious birders should allow two to three days and use a specialist guide, since many of the targets are skulking understorey species.','Half day to full day','moderate',50,150,187500,562500,'Guide fee USD 50–150 per group per day plus park entry.','12 and above recommended','["Binoculars","Field guide","Rain cover for optics","Neutral clothing"]','Mar–May and Sep–Nov for breeding plumage and migrants','nature',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (1,'bwindi-forest-walks','Guided Forest & Waterfall Walks','fa-person-hiking','Six marked trails run from Buhoma, the most popular being the Munyaga River trail to a set of three small waterfalls and the longer Ivi River trail. These are a good option on a non-trekking day and a sensible warm-up if you arrive the afternoon before your permit.','2–6 hours','moderate',30,50,112500,187500,'USD 30–50 per person including ranger guide.','8 and above','["Walking shoes","Water","Rain jacket"]','All year','nature',4);
