INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (2,'murchison-falls-national-park','Murchison Falls National Park','Murchison Falls','The Nile forced through a seven-metre gorge',4,'Nwoya, Buliisa, Kiryandongo & Masindi','North-western Uganda, straddling the Victoria Nile',2.2611,31.68,'https://sspark.genspark.ai/i/8kBhnQ3GVBeWIMh8?width=2560','https://sspark.genspark.ai/i/xjBBl53RbmlIqwSi?width=2560','Uganda''s largest and oldest national park, where the entire Victoria Nile is squeezed through a seven-metre cleft and drops 43 metres into the Devil''s Cauldron.','At 3,893 km² Murchison is the biggest protected area in Uganda, and the falls themselves are the most physically impressive thing in the country. The Nile arrives carrying the outflow of Lake Victoria, hits a narrow break in the rift escarpment and is compressed from a river hundreds of metres wide into a gap you could almost jump across. The resulting pressure — an estimated 300 cubic metres of water per second through that gap — is why it is sometimes described as the most powerful waterfall in the world by force rather than height.
INSERT INTO destination_categories (destination_id,category_id) VALUES (2,1);
