INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'launch-to-the-falls','Launch Trip to the Base of the Falls','fa-ship','A three-hour return boat trip from Paraa upstream to where the Nile crashes out of the gorge. The boat gets within a few hundred metres of the falls, and the run up gives you dense concentrations of hippo, enormous crocodiles hauled out on the sandbanks, elephant and buffalo drinking, and excellent water birds. The single best thing to do is to disembark at the turnaround and walk the steep path to the top of the falls, arranging for your vehicle to meet you there.','3 hours','easy',30,45,112500,168750,'USD 30 per person on the scheduled UWA launch; private charters USD 200–400 per boat. The top-of-falls hike is included if arranged in advance.','All ages','["Sun hat","Sunscreen","Water","Camera with zoom","Light rain shell for spray"]','All year; highest water Apr–May and Oct–Nov','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'buligi-game-drive','Buligi Circuit Game Drive','fa-binoculars','The northern bank''s network of tracks between the Victoria and Albert Niles is the park''s prime game viewing area. Leave at 06:30 for the best activity. The open borassus palm savanna holds the world''s largest population of Rothschild''s giraffe, and lion are regularly seen on the Albert delta track. A ranger guide costs little and substantially improves what you find.','3–4 hours','easy',20,40,75000,150000,'Ranger guide USD 20–30 per vehicle. Vehicle hire USD 150–250 per day if not already arranged.','All ages','["Binoculars","Camera","Light clothing","Water"]','Dec–Feb and Jun–Sep best','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'top-of-the-falls','Top of the Falls Hike','fa-mountain-sun','A 45-minute climb from the river to the lip of the gorge, ending at a viewpoint directly above the point where the Nile is forced through the gap. You feel the ground vibrating. There is a walkway across the top and several viewpoints, and the spray produces rainbows through most of the morning. Steep and fully exposed to the sun.','1–2 hours','moderate',0,0,0,0,'No additional fee beyond park entry; access is by vehicle or on foot from the launch turnaround.','8 and above','["Sturdy shoes","Water","Hat","Waterproof camera bag"]','All year','adventure',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'kaniyo-pabidi-chimps','Chimpanzee Tracking, Kaniyo Pabidi','fa-hippo','The mahogany forest of Kaniyo Pabidi in the Budongo reserve, just inside the southern gate, holds a habituated chimpanzee community. Tracking is flatter and easier than Kibale and success rates are good, though the groups are smaller. It combines neatly with the drive in or out of the park.','3–4 hours','moderate',90,130,337500,487500,'USD 90–130 per person for foreign non-residents.','12 and above','["Walking shoes","Long trousers","Insect repellent","Water"]','All year','wildlife',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'nile-delta-shoebill','Nile Delta Birding Cruise','fa-dove','A downstream boat trip to where the Victoria Nile spreads into Lake Albert. This is one of Uganda''s most reliable shoebill sites outside Mabamba, and the delta also produces Goliath heron, saddle-billed stork, African skimmer and enormous numbers of waterfowl. Departures are early morning.','4–5 hours','easy',100,150,375000,562500,'USD 100–150 per person, or private charter from USD 350 per boat.','All ages','["Binoculars","Bird guide","Sun protection","Warm layer for early start"]','Jan–Mar best for shoebill visibility','nature',4);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (2,'murchison-fishing','Sport Fishing Below the Falls','fa-fish','The turbulent water immediately below the falls holds very large Nile perch — fish over 100 kg have been recorded — along with tigerfish and catfish. Fishing is catch-and-release from designated spots reached by boat, with a ranger present. You need a UWA fishing permit and should bring or hire heavy tackle.','Half or full day','moderate',50,150,187500,562500,'Permit USD 50 per day plus boat transfer; tackle hire extra.','12 and above','["Heavy tackle if you have it","Sun protection","Gloves","Water"]','Dec–Mar when water is lower','adventure',5);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (2,'https://sspark.genspark.ai/i/xjBBl53RbmlIqwSi?width=2560','The Nile squeezes through a 7-metre gap before crashing 43 metres into the Devil''s Cauldron','Landscape','Licensed imagery',1,0);
