INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (2,'https://sspark.genspark.ai/i/Q4MxYFUCIIrCK4bo?width=2560','Early morning game drive on the Buligi circuit','Activities','Licensed imagery',0,4);
