INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (3,'queen-elizabeth-national-park','Queen Elizabeth National Park','Queen Elizabeth','Tree-climbing lions and a channel full of hippo',3,'Kasese, Rubirizi, Rukungiri & Kamwenge','Western Uganda, between Lakes George and Edward below the Rwenzori',-0.1667,30,'https://sspark.genspark.ai/i/lSRSCJsMkn1GhiYT?width=2560','https://sspark.genspark.ai/i/2gdELxXVmat0mRKV?width=2560','Uganda''s most visited savanna park, spread across the rift floor between two lakes with the Rwenzori glaciers on one horizon and volcanic craters on the other.','Queen Elizabeth covers 1,978 km² of remarkably varied ground. The Kazinga Channel, a 32 km natural waterway, links Lake George to Lake Edward and runs right through the middle of the park — the boat trip along it delivers the densest concentration of hippo in Uganda plus buffalo, elephant and an extraordinary volume of birdlife. To the north the Kasenyi plains are open grassland where lion follow the Uganda kob breeding grounds. To the west the Katwe explosion craters give views back across the whole rift. And in the far south, separated by a two-hour drive, the **Ishasha sector** holds the tree-climbing lions the park is famous for.
INSERT INTO destination_categories (destination_id,category_id) VALUES (3,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (3,6);
