INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'kazinga-channel-cruise','Kazinga Channel Boat Launch','fa-ship','Two hours along the channel between Lakes George and Edward, and the single best-value activity in the Ugandan park system. The banks are lined with hippo pods, buffalo come down to drink within metres of the boat, elephants cross, and the bird list on a good afternoon runs past eighty species including African skimmer, pied kingfisher in enormous numbers and saddle-billed stork.','2 hours','easy',30,45,112500,168750,'USD 30 per person on the scheduled UWA launch from Mweya; private charter USD 150–300 per boat.','All ages','["Sun hat","Binoculars","Camera","Water"]','All year','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'ishasha-lions','Ishasha Tree-Climbing Lion Drive','fa-cat','A game drive through the park''s southern sector looking for the prides that rest in fig and acacia branches. Go early morning or late afternoon with a ranger who has current information on where the lions have been lying up. The sector is also excellent for topi, which occur here and almost nowhere else in the park, and for elephant along the Ntungwe river.','3–4 hours','easy',20,40,75000,150000,'Ranger guide USD 20–30 per vehicle on top of park entry.','All ages','["Binoculars","Long lens","Water","Patience"]','Jun–Sep and Jan–Feb for road access','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'kyambura-chimps','Kyambura Gorge Chimpanzee Tracking','fa-hippo','The Kyambura Gorge is a 100 m deep forested cut through the savanna, holding a small isolated chimpanzee community. You descend into the gorge and track on foot along the river. It is a striking landscape and a good half-day, but be clear that the success rate is roughly 50-60%, well below Kibale.','3 hours','moderate',50,60,187500,225000,'USD 50 per person for foreign non-residents.','12 and above','["Walking shoes","Long trousers","Insect repellent","Water"]','All year','wildlife',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'lion-tracking-experience','Experiential Lion Tracking','fa-location-crosshairs','You join Uganda Carnivore Program researchers using radio telemetry to locate collared lions on the Kasenyi plains, off the normal tracks and often before sunrise. Group sizes are small, you learn how the monitoring works, and the sightings are usually far closer and longer than on a standard drive.','3–4 hours','easy',100,150,375000,562500,'USD 100–150 per person; book ahead as daily places are limited.','12 and above','["Warm layer","Camera","Binoculars"]','All year','wildlife',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'katwe-crater-drive','Katwe Explosion Crater Drive','fa-mountain','A 27 km loop along the crater rim north-west of Mweya, running past a series of explosion craters and the salt workings at Lake Katwe, where salt has been extracted by hand for more than seven hundred years. The viewpoints across the rift to the Rwenzori are the best in the park.','2–3 hours','easy',0,20,0,75000,'No extra park fee; a local guide at Lake Katwe salt works costs USD 10–20.','All ages','["Camera","Sun protection","Cash for the community guide"]','All year; clearest mountain views Jun–Sep','nature',4);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (3,'maramagambo-bat-cave','Maramagambo Forest & Bat Cave','fa-leaf','Guided walks in one of Uganda''s larger surviving forest blocks, with the main draw a bat cave viewed from a protective enclosure — the cave holds a huge Egyptian fruit bat colony and the pythons that prey on them. Also good for forest primates and the two crater lakes nearby.','2–4 hours','easy',30,50,112500,187500,'USD 30–50 per person with ranger guide.','8 and above','["Closed shoes","Insect repellent","Torch"]','All year','nature',5);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (3,'https://sspark.genspark.ai/i/lSRSCJsMkn1GhiYT?width=2560','Ishasha''s tree-climbing lions rest in fig branches through the heat of the day','Wildlife','Licensed imagery',1,0);
