INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (3,'https://sspark.genspark.ai/i/vfI8QFq3TBfSBbIA?width=2560','Buffalo and hippo crowd the channel banks on the afternoon launch','Wildlife','Licensed imagery',0,2);
