INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (3,'https://sspark.genspark.ai/i/egAr8rF806DNvsTX?width=2560','Game drive at first light on the Kasenyi plains','Activities','Licensed imagery',0,5);
