INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (4,'kidepo-valley-national-park','Kidepo Valley National Park','Kidepo','Uganda''s true wilderness, and worth every hour of the drive',4,'Kaabong & Karenga','Far north-eastern Uganda, at the South Sudan and Kenya borders',3.8833,33.8833,'https://sspark.genspark.ai/i/j6hTevTHVX0by30V?width=2560','https://sspark.genspark.ai/i/wI86dlcOBPOSZvyi?width=2560','A 1,442 km² semi-arid wilderness in the Karamoja corner, with mountains on three horizons, species found nowhere else in Uganda, and almost no other vehicles.','Kidepo is the park that experienced Africa travellers rate highest and most visitors never reach, because it is 700 km and ten to twelve hours of driving from Kampala. What that distance buys is a landscape on a completely different scale to the rest of Uganda: open dry savanna ringed by the Morungole, Lotukei and Napore ranges, with the Kidepo and Narus valleys cutting across it.
INSERT INTO destination_categories (destination_id,category_id) VALUES (4,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (4,6);
INSERT INTO destination_categories (destination_id,category_id) VALUES (4,7);
INSERT INTO destination_categories (destination_id,category_id) VALUES (4,5);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (4,'narus-valley-drive','Narus Valley Game Drive','fa-binoculars','The park''s core game viewing circuit, running through open grassland that holds water year-round. Expect large buffalo herds, lion on the rocks and in the riverine strips, elephant, zebra, hartebeest and eland, with the Morungole and Napore ranges filling the horizon in every direction. Cheetah are present but scarce.','4–6 hours','easy',20,40,75000,150000,'Ranger guide USD 20–30 per vehicle. 4x4 essential.','All ages','["Binoculars","Long lens","3 litres of water","Dust protection"]','Sep–Mar','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (4,'kanangorok-springs','Kanangorok Hot Springs Drive','fa-hot-tub-person','A long drive north-east across the dry Kidepo Valley and its borassus palm forest to hot springs a few kilometres short of the South Sudan border. The springs themselves are modest; the point is the drive, the emptiness and the sense of being at the very edge of the country. Allow most of a day and take a ranger.','6–8 hours','moderate',30,50,112500,187500,'Ranger guide USD 30 per vehicle; fuel cost is significant given the distance.','10 and above','["Plenty of water","Packed lunch","Sun protection","Spare fuel"]','Dec–Mar when the sand river is dry','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (4,'ik-community-hike','Ik Community Hike, Mount Morungole','fa-person-hiking','The Ik are one of Uganda''s smallest ethnic groups, living in settlements high on Mount Morungole. Reaching them is a demanding four to six hour climb each way with a guide and a ranger, and the visit is arranged through the community. It is the most serious cultural undertaking available in the Ugandan parks and should not be treated casually.','Full day, 8–12 hours','expert',100,180,375000,675000,'USD 100–180 per person including community fees, guide and ranger escort.','16 and above with good fitness','["Proper hiking boots","3 litres of water","Packed food","Gifts or cash for the community"]','Dec–Mar; avoid the rains entirely','culture',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (4,'karamojong-manyatta','Karamojong Manyatta Visit','fa-drum','Guided visits to a Karamojong homestead outside the park, where you see the thorn-fenced manyatta layout, cattle-centred pastoralist life, metalwork, beadwork and dance. Karamoja has been Uganda''s most marginalised region and these visits are a direct income stream for the communities involved.','2–3 hours','easy',30,60,112500,225000,'USD 30–60 per group, paid to the community.','All ages','["Cash for crafts","Respectful clothing","Ask before photographing"]','All year','culture',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (4,'kidepo-bush-walk','Guided Bush Walk','fa-shoe-prints','Ranger-led walks from Apoka along the Narus river or up onto the nearby ridges. Walking changes your relationship to the landscape completely after days in a vehicle, and rangers read tracks, spoor and plant use as you go. Armed escort is mandatory.','2–4 hours','moderate',30,40,112500,150000,'USD 30 per person with armed ranger.','12 and above','["Closed walking shoes","Neutral colours","Water","Hat"]','Sep–Mar','adventure',4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (4,'https://sspark.genspark.ai/i/j6hTevTHVX0by30V?width=2560','The Narus Valley holds water through the dry season and concentrates the game','Landscape','Licensed imagery',1,0);
