INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (4,'https://sspark.genspark.ai/i/smj263J03FU6oGOW?width=2560','Open plains stretching towards the South Sudan border','Landscape','Licensed imagery',0,2);
