INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (5,'kibale-national-park','Kibale National Park','Kibale','The primate capital of East Africa',3,'Kamwenge & Kabarole','Western Uganda, just south-east of Fort Portal',0.4833,30.3833,'https://sspark.genspark.ai/i/JNEclPPcXQGmhNyr?width=2560','https://sspark.genspark.ai/i/Anj6vtWSLT7LGBay?width=2560','A 795 km² block of tall tropical rainforest holding thirteen primate species and around 1,500 chimpanzees — the highest concentration of primates in East Africa.','Kibale is the best place in Africa to track chimpanzees, and the reason is a combination of habituation and terrain. The Kanyanchu community has been visited by researchers and tourists since 1993, so the animals are entirely relaxed around people, and success rates run above 90%. The forest floor is also comparatively flat and the trails well maintained, which makes this a far less punishing experience than gorilla trekking in Bwindi.
INSERT INTO destination_categories (destination_id,category_id) VALUES (5,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (5,11);
