INSERT INTO destination_categories (destination_id,category_id) VALUES (5,12);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (5,'chimpanzee-tracking','Chimpanzee Tracking','fa-hippo','You meet at Kanyanchu for a 07:30 or 14:00 briefing, then walk into the forest in a group of up to six with a ranger guide. Trackers have usually located the community already. Once you find them you have one hour, and because the chimps are entirely habituated they carry on feeding, grooming and calling at close range. Success rates are above 90%.','3–4 hours','moderate',250,250,937500,937500,'USD 250 per person for foreign non-residents; USD 200 foreign residents; UGX 150,000 East African citizens.','12 and above','["Long trousers","Closed shoes","Rain jacket","Insect repellent","Camera"]','All year','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (5,'chimp-habituation','Chimpanzee Habituation Experience','fa-clock','A full day with a chimpanzee community, joining them at around 06:00 as they leave their night nests and staying with them until they build new ones in the late afternoon. Group sizes are very small. You watch a complete day of chimpanzee life — hunting, territorial patrols, social politics — rather than a single hour''s encounter, and the researchers explain what you are seeing.','Full day, 10–12 hours','challenging',300,300,1125000,1125000,'USD 300 per person for foreign non-residents. Run during the low-visitor months of March-May and November-January.','12 and above','["Packed breakfast and lunch","2 litres of water","Full waterproofs","Head torch"]','Mar–May and Nov–Jan','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (5,'bigodi-wetland-walk','Bigodi Wetland Sanctuary Walk','fa-dove','A community-managed swamp on the park''s southern boundary, walked on boardwalks and trails with guides from the Kibale Association for Rural and Environmental Development. Eight primate species use the swamp, and the bird list runs to around 200 including the great blue turaco and papyrus gonolek. All revenue funds local schools and clinics.','3 hours','easy',30,40,112500,150000,'USD 30–40 per person, paid directly to the community association.','All ages','["Binoculars","Closed shoes","Insect repellent","Rain jacket"]','All year','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (5,'kibale-night-walk','Forest Night Walk','fa-moon','A guided walk from Kanyanchu after dark with torches, looking for the nocturnal half of the forest: potto, bushbaby, tree hyrax, civet, and occasionally a nightjar or an owl. The soundscape alone justifies it. Departures around 19:30.','1.5–2 hours','easy',40,50,150000,187500,'USD 40–50 per person including ranger and torch hire.','8 and above','["Closed shoes","Long sleeves","Torch","Insect repellent"]','All year','nature',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (5,'kibale-birding','Forest Birding','fa-binoculars','Kibale records around 375 species, and the star target is the green-breasted pitta — one of Africa''s most sought-after birds, best looked for on early morning walks from Kanyanchu between June and August. The forest also holds Nahan''s francolin, black bee-eater and a long list of forest specials.','Half or full day','moderate',50,120,187500,450000,'Specialist bird guide USD 50–120 per group per day plus park entry.','12 and above','["Binoculars","Field guide","Neutral clothing","Rain cover for optics"]','Jun–Aug for pitta displays','nature',4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (5,'https://sspark.genspark.ai/i/Anj6vtWSLT7LGBay?width=2560','Tall tropical forest with a closed canopy reaching 55 metres','Landscape','Licensed imagery',1,0);
