INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (6,'lake-mburo-national-park','Lake Mburo National Park','Lake Mburo','Zebra, walking safaris and no lions',3,'Kiruhura & Mbarara','Western Uganda, directly on the Kampala–Mbarara highway',-0.6,30.95,'https://sspark.genspark.ai/i/PJinRcVIQ1gmwTqS?width=2560','https://sspark.genspark.ai/i/zpuEe8D54ZMmKcjA?width=2560','Uganda''s smallest savanna park, built around a chain of wetlands, and the most convenient real safari stop on the road west — with walking safaris because there are no lions.','At 370 km² Mburo is compact, and its great practical virtue is location: the gate is about twenty minutes off the Kampala-Mbarara highway, roughly four hours from the capital, which makes it the natural first or last night of almost any western itinerary and a genuinely feasible weekend safari from Kampala.
INSERT INTO destination_categories (destination_id,category_id) VALUES (6,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (6,6);
