INSERT INTO destination_categories (destination_id,category_id) VALUES (6,7);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (6,'mburo-walking-safari','Guided Walking Safari','fa-shoe-prints','Because there are no resident lions, Mburo permits walking among plains game with an armed ranger. Morning departures from Rwonyo take you across the valley grassland and up to the salt lick, typically getting within fifty metres of zebra, impala and eland. Being on foot changes the experience entirely — you notice tracks, dung, birds and the sound of the place.','2–3 hours','easy',30,40,112500,150000,'USD 30 per person with armed ranger guide.','12 and above','["Closed shoes","Neutral colours","Hat","Water"]','All year; firmer ground Jun–Aug and Dec–Feb','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (6,'mburo-boat-trip','Lake Mburo Boat Trip','fa-ship','A two-hour launch on Lake Mburo itself, good for large hippo pods, crocodile hauled out on the banks, and a strong bird list including the elusive African finfoot, malachite and pied kingfishers, and the occasional shoebill in the papyrus fringes.','2 hours','easy',20,30,75000,112500,'USD 20–30 per person on the scheduled launch.','All ages','["Binoculars","Sun hat","Camera"]','All year','nature',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (6,'mburo-horseback','Horseback Safari','fa-horse','Operated from Mihingo Lodge, riding among zebra, impala and eland which tolerate horses far more readily than vehicles or walkers. Rides range from an hour''s introduction to full-day excursions with a bush lunch, and both novice and experienced riders are catered for.','1–6 hours','moderate',50,170,187500,637500,'USD 50 for a one-hour ride up to USD 170 for a full day with lunch.','10 and above','["Long trousers","Closed shoes with a heel","Hat","Sunscreen"]','Jun–Aug and Dec–Feb best','adventure',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (6,'mburo-night-drive','Night Game Drive','fa-moon','A two-hour drive after dark with a ranger and spotlight, looking for the nocturnal species you will not see by day: leopard, spotted hyena, white-tailed mongoose, genet, bushbaby and nightjars on the tracks. Departures around 19:00.','2 hours','easy',30,50,112500,187500,'USD 30 per person plus ranger fee; your own or lodge vehicle required.','8 and above','["Warm layer","Torch","Camera with high ISO capability"]','All year','wildlife',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (6,'mburo-cycling','Cycling & Quad Biking','fa-bicycle','Mountain biking and quad biking run on the community land and tracks around the park boundary, through Ankole cattle country and local villages. A good active half-day and a direct way to see rural life alongside the wildlife.','2–4 hours','moderate',40,90,150000,337500,'USD 40–90 per person depending on operator and duration.','14 and above for quads','["Closed shoes","Sunglasses","Long sleeves","Water"]','Dry months preferred','adventure',4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (6,'https://sspark.genspark.ai/i/zpuEe8D54ZMmKcjA?width=2560','Burchell''s zebra — Lake Mburo is the easiest place in Uganda to see them','Wildlife','Licensed imagery',1,0);
