INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (7,'jinja','Jinja','Jinja','East Africa''s adventure capital on the Nile',2,'Jinja','Eastern Uganda, where the Nile leaves Lake Victoria',0.4244,33.2041,'https://sspark.genspark.ai/i/0gBJt3LP2OUMPQRY?width=2560','https://sspark.genspark.ai/i/3VAwu2uIFw5I2zah?width=2560','The town at the source of the Nile, and the centre of adventure tourism in East Africa — Grade V rafting, bungee jumping and kayaking on warm water that runs all year.','Jinja earns its reputation on the river. The Victoria Nile leaves Lake Victoria here and drops through a series of big-volume rapids that produce some of the best commercial white water in the world: warm, clean, deep water with forgiving pool-drop sections between rapids, which is why beginners can safely run Grade V here in a way that would be unthinkable on a cold, rocky river.
INSERT INTO destination_categories (destination_id,category_id) VALUES (7,7);
INSERT INTO destination_categories (destination_id,category_id) VALUES (7,9);
INSERT INTO destination_categories (destination_id,category_id) VALUES (7,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (7,2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'nile-rafting','White Water Rafting','fa-water','A full day running roughly 25 km of the Victoria Nile through named rapids including Overtime, Itanda and Nile Special. Grade V sections are interspersed with long calm pools where you can swim, and safety kayakers accompany the rafts throughout. Half-day and Grade III family options are available. Warm water and a pool-drop profile make this genuinely suitable for complete beginners.','Full day, 6–8 hours','moderate',125,175,468750,656250,'USD 125–175 per person for a full day including transport from Kampala or Jinja, lunch on the river and a meal afterwards. Half-day around USD 95–125.','7+ for Grade III family trips; 15+ for Grade V','["Swimwear","Quick-dry shirt","Strapped sandals","Sunglasses strap","Waterproof sunscreen","Dry change of clothes"]','All year — the river is dam-regulated','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'nile-bungee','Nile Bungee Jump','fa-arrow-down','A 44 m jump from a cantilevered platform over the Nile, with the option of a water touch at the bottom of the arc. Tandem jumps and a rocket-launch variant are offered. Operated to international safety standards with full-body harness available as well as ankle attachment.','1–2 hours including briefing','moderate',115,135,431250,506250,'USD 115–135 per jump; tandem jumps priced per pair.','13 and above with parental consent; minimum weight applies','["Secure clothing","Nothing in pockets","Contact lenses rather than glasses"]','All year','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'source-of-nile-boat','Source of the Nile Boat Trip','fa-ship','A short boat trip from the Source of the Nile gardens out to the point where Lake Victoria empties into the river, where you can see the spring water welling up and a clear colour change. Guides cover Speke''s 1862 expedition and the site''s history. Best in the late afternoon.','1–1.5 hours','easy',10,25,37500,93750,'UGX 40,000–90,000 per boat, typically shared between passengers, plus the gardens entry fee.','All ages','["Sun hat","Camera","Light jacket for the breeze"]','All year','culture',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'jinja-kayaking','Kayaking & River Surfing','fa-person-swimming','Jinja is one of the world''s best places to learn whitewater kayaking — warm water, big friendly features and a resident community of professional instructors. Introductory flat-water courses run through to multi-day whitewater progression, and tandem trips let complete beginners run rapids with an expert in the back.','Half day to multi-day','challenging',60,400,225000,1500000,'USD 60–90 for an introductory session; multi-day courses USD 250–400.','12 and above, must be able to swim','["Swimwear","Quick-dry clothes","Sunscreen","Water bottle"]','All year','adventure',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'jinja-quad-biking','Quad Biking & Village Trails','fa-motorcycle','Guided quad bike trails through the villages, sugar cane and riverside tracks around Bujagali. Routes range from a one-hour introduction to half-day expeditions, all on machines with training given first. A good way to see rural life along the Nile at a pace that allows stopping.','1–4 hours','easy',45,120,168750,450000,'USD 45 for one hour up to USD 120 for a half-day trail.','16 and above to drive; younger children can ride as passengers','["Long trousers","Closed shoes","Sunglasses","Bandana for dust"]','All year; dustier in dry months','adventure',4);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (7,'jinja-sunset-cruise','Sunset Cruise on the Nile','fa-champagne-glasses','A relaxed two-hour boat cruise upstream from Bujagali, usually with drinks and snacks included, watching fish eagles and the light going down over the river. The antidote to a day of adrenaline, and the most popular evening activity in Jinja.','2 hours','easy',25,50,93750,187500,'USD 25–50 per person depending on operator and whether drinks are included.','All ages','["Light jacket","Camera","Insect repellent"]','All year','relaxation',5);
