INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (8,'source-of-the-nile','Source of the Nile','Source of the Nile','Where the world''s longest river begins',2,'Jinja','Jinja, on the northern shore of Lake Victoria',0.4225,33.1984,'https://sspark.genspark.ai/i/4ZO6lsY8DLiJXLhL?width=2560','https://sspark.genspark.ai/i/D8CUVK0y1tZyIAaK?width=2560','The point where Lake Victoria empties into the Victoria Nile, identified by John Hanning Speke in 1862 and marked today by a monument and gardens on the Jinja bank.','The search for the Nile''s source was the great geographical obsession of nineteenth-century Europe, and this is where it ended. Speke reached the outflow in July 1862 and named the cascade here Ripon Falls after the president of the Royal Geographical Society. Those falls were submerged in 1954 by the Owen Falls Dam, so what you see now is a broad, calm outflow rather than a rapid — but the geography is unchanged: this is where the water that will travel 6,650 km to the Mediterranean begins its journey.
