INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (8,'nile-source-boat','Boat Trip to the Source','fa-ship','A 45-90 minute boat trip from the gardens out to the exact outflow point, where underwater springs create a visible boil on the surface and the water changes colour where lake meets river. Guides cover Speke''s expedition, the drowned Ripon Falls and the dam. Excellent for fish eagles and cormorants.','45–90 minutes','easy',10,25,37500,93750,'UGX 40,000–90,000 per boat return, split between passengers. Negotiate at the jetty.','All ages; life jackets provided','["Sun hat","Camera","Light jacket"]','All year','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (8,'speke-monument-walk','Speke Monument & Gardens Walk','fa-monument','A guided or self-guided walk through the landscaped gardens taking in the Speke Monument, the Gandhi memorial, interpretive plaques and viewpoints over the outflow. Local guides are available at the entrance and are worth taking for the historical context.','1–2 hours','easy',3,10,11250,37500,'Gardens entry UGX 10,000-20,000 for non-residents; guide fees negotiated, typically UGX 20,000-40,000.','All ages','["Sun hat","Water","Small notes for crafts"]','All year','history',1);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (8,'https://sspark.genspark.ai/i/4ZO6lsY8DLiJXLhL?width=2560','The Speke Monument and gardens on the Jinja bank','Culture','Licensed imagery',1,0);
