INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (9,'bujagali','Bujagali','Bujagali','The river base for Uganda''s adventure scene',2,'Jinja','On the Victoria Nile, 8 km north of Jinja town',0.4903,33.135,'https://sspark.genspark.ai/i/fXh9GMzCc645qMN7?width=2560','https://sspark.genspark.ai/i/lsyXEdAL30WRVbBy?width=2560','The stretch of the Nile where almost every rafting, kayaking and riverside camp in Uganda is based — and where the original Bujagali Falls stood before the 2012 dam.','Bujagali was, until 2012, a set of rapids that functioned as Uganda''s most famous natural attraction after Murchison. The Bujagali hydroelectric dam raised the water level and submerged the falls themselves, a genuinely contested decision that displaced communities and drew sustained opposition. What remains is a broad reservoir above the dam and, below it, the rapids that make the commercial rafting industry work.
INSERT INTO destination_categories (destination_id,category_id) VALUES (9,7);
INSERT INTO destination_categories (destination_id,category_id) VALUES (9,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (9,2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (9,'bujagali-riverboarding','Riverboarding & Body Surfing','fa-water','Running the rapids on a bodyboard with fins rather than in a raft — far more intense, far wetter, and only for confident swimmers. Guides pick lines through the smaller Grade III features and you surf the standing waves. Usually combined with a rafting day.','Half day','challenging',80,130,300000,487500,'USD 80–130 per person, often discounted when combined with rafting.','16 and above, strong swimmers only','["Swimwear","Rash vest","Strapped sandals","Sunscreen"]','All year','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (9,'bujagali-village-walk','Community & Village Walk','fa-people-group','Guided walks from the riverside camps through the surrounding villages, covering the pre-dam history of the falls and the Basoga shrine, smallholder farming, and daily life on the river. Arranged through the camps and guided by residents.','2–3 hours','easy',15,35,56250,131250,'USD 15–35 per person, paid to the community guide.','All ages','["Walking shoes","Sun hat","Cash for crafts","Ask before photographing people"]','All year','culture',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (9,'bujagali-sup','Stand-Up Paddleboarding','fa-person-swimming','Flat-water paddleboarding on the reservoir above the dam, with instruction for beginners and longer downstream paddles for the more confident. Early morning is calmest and best for birdlife along the banks.','1–3 hours','easy',30,60,112500,225000,'USD 30–60 per person including board, paddle and buoyancy aid.','10 and above, must be able to swim','["Swimwear","Sun hat","Waterproof sunscreen","Water bottle"]','All year','adventure',2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/fXh9GMzCc645qMN7?width=2560','The Nile at Bujagali, launch point for most rafting trips','Landscape','Licensed imagery',1,0);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/lsyXEdAL30WRVbBy?width=2560','Kayaking and rafting operators are based along this stretch','Activities','Licensed imagery',0,1);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/02yu3YtR5FBof2CY?width=2560','The original Bujagali Falls were submerged by the dam in 2012','Landscape','Licensed imagery',0,2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/NFZa6TcFYiGElhTp?width=2560','Rapids downstream of the dam still run Grade IV-V','Activities','Licensed imagery',0,3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/1DqDKGvNQlqKmdPe?width=2560','Riverside camps and backpacker lodges line the bank','Accommodation','Licensed imagery',0,4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (9,'https://sspark.genspark.ai/i/R1qTp0obmi3jBEi2?width=2560','Quiet water above the rapids','Landscape','Licensed imagery',0,5);
INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (10,'sipi-falls','Sipi Falls','Sipi Falls','Three waterfalls, arabica coffee and the Karamoja plains below',2,'Kapchorwa','Eastern Uganda, on the western slopes of Mount Elgon',1.3333,34.3833,'https://sspark.genspark.ai/i/uBXiVOoU87yPYvMT?width=2560','https://sspark.genspark.ai/i/MggJNyP25JOJgyGb?width=2560','A series of three waterfalls on the Sipi River, the largest dropping about 100 metres, set among arabica coffee terraces at 1,775 m with the Karamoja plains stretching out below.','Sipi is the most photographed place in eastern Uganda and one of the few destinations that genuinely delivers on its images. The Sipi River drops off the Mount Elgon escarpment in three distinct falls: the lowest and largest is around 100 m and the one you see in every photograph, with two smaller falls of roughly 85 m and 75 m further up the valley. A circuit walk links all three and takes about four hours.
INSERT INTO destination_categories (destination_id,category_id) VALUES (10,2);
INSERT INTO destination_categories (destination_id,category_id) VALUES (10,4);
