INSERT INTO destination_categories (destination_id,category_id) VALUES (10,11);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (10,'three-falls-walk','Three Waterfalls Circuit Walk','fa-person-hiking','A guided circuit linking all three falls on the Sipi River, taking roughly four hours. You get to the base of the main 100 m fall — expect spray — then climb through coffee terraces and smallholdings to the middle and upper falls, with a cave behind one of them. Steep, occasionally slippery, and consistently spectacular.','3–4 hours','moderate',5,15,18750,56250,'UGX 15,000–40,000 per person with a community guide; less per head for larger groups.','8 and above','["Walking shoes with grip","Rain jacket","Water","Camera"]','All year; best flow Apr–May and Oct–Nov','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (10,'sipi-abseiling','Abseiling the Main Fall','fa-arrow-down','A commercial abseil of about 100 m down the rock face beside the main waterfall, run with full harness, helmet and instruction from local operators. No prior experience needed, though it is not for anyone uneasy with heights. You get wet.','2–3 hours','challenging',35,60,131250,225000,'USD 35–60 per person including all equipment and instruction.','14 and above with parental consent','["Clothes you do not mind soaking","Closed shoes","Change of clothes"]','All year; drier months preferred for grip','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (10,'sipi-coffee-tour','Arabica Coffee Farm Tour','fa-mug-hot','Smallholder farms around Sipi grow high-altitude arabica and process much of it by hand. Tours take you through picking, pulping, washing, drying, hulling and roasting over an open fire, finishing with a cup brewed from beans you watched being processed. Excellent value and the money goes to the farming families.','2–3 hours','easy',8,20,30000,75000,'UGX 25,000–60,000 per person, paid to the farm or community group.','All ages','["Sun hat","Walking shoes","Cash to buy coffee"]','All year; harvest and processing Oct–Feb','culture',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (10,'sipi-sunset-viewpoint','Escarpment Sunset Walk','fa-sun','A short walk to the escarpment viewpoints above the lodges, looking west over the Karamoja plains as the sun goes down. On a clear evening you can see for well over a hundred kilometres. Free, easy, and the thing most visitors remember.','1–2 hours','easy',0,5,0,18750,'Free; a local guide costs UGX 10,000-20,000 if you want one.','All ages','["Fleece","Torch for the walk back","Camera"]','All year; clearest Dec–Feb','relaxation',3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/uBXiVOoU87yPYvMT?width=2560','The main 100-metre drop, the lowest and largest of the three falls','Landscape','Licensed imagery',1,0);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/MggJNyP25JOJgyGb?width=2560','Sipi sits at 1,775 m on the western slopes of Mount Elgon','Landscape','Licensed imagery',0,1);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/XrMWMVevcDujk2Jf?width=2560','Abseiling the main fall — around 100 m of rope work','Activities','Licensed imagery',0,2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/vRUkNDzNWYGNIXWe?width=2560','The three-waterfall circuit takes roughly four hours on foot','Activities','Licensed imagery',0,3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/6agSrdsouaeAhVdD?width=2560','Arabica coffee grows on the surrounding terraces','Culture','Licensed imagery',0,4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/THjVAXxjFo1tPpUO?width=2560','Views back over the Karamoja plains on a clear morning','Landscape','Licensed imagery',0,5);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/rM08mzMmYi9Mk2HV?width=2560','The upper falls, reached by a steeper path','Landscape','Licensed imagery',0,6);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/cb8rLb41wcjbbxaB?width=2560','Descending beside the main cascade','Activities','Licensed imagery',0,7);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (10,'https://sspark.genspark.ai/i/EZRqWnxRw3HNNVE6?width=2560','Sipi in full flow after rain','Landscape','Licensed imagery',0,8);
INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (11,'lake-bunyonyi','Lake Bunyonyi','Lake Bunyonyi','Twenty-nine islands and no crocodiles',3,'Kabale & Rubanda','South-western Uganda, near Kabale at 1,950 m',-1.2833,29.9333,'https://sspark.genspark.ai/i/LntnsKGVC8NrxKEy?width=2560','https://sspark.genspark.ai/i/PnxuSqtu4lF1LiI4?width=2560','A deep highland lake scattered with twenty-nine islands, ringed by terraced hills, and — with no crocodiles, hippos or bilharzia — the one place in Uganda where you can safely swim in a lake.','Bunyonyi means "place of many little birds", and it sits at 1,950 m in the hills of the far south-west. Its depth is disputed — figures between 40 m and 900 m circulate, and it is often claimed to be Africa''s second-deepest lake — but what is certain is that the water is clean, warm enough to swim in, and free of the hazards that make swimming inadvisable elsewhere in Uganda.
INSERT INTO destination_categories (destination_id,category_id) VALUES (11,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (11,8);
INSERT INTO destination_categories (destination_id,category_id) VALUES (11,5);
INSERT INTO destination_categories (destination_id,category_id) VALUES (11,12);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (11,'bunyonyi-canoe-trip','Dugout Canoe Island Tour','fa-sailboat','A paddled or motorised trip between the islands with a local guide, usually taking in Punishment Island, Bwama — site of a former leprosy hospital founded in 1921 — and Bushara. The guides know the history of each island and the lake''s formation, and the water-level views of the terraced hills are the best you will get.','2–4 hours','easy',10,35,37500,131250,'UGX 40,000–120,000 per boat depending on duration and whether it is paddled or motorised; split between passengers.','All ages; life jackets available','["Sun hat","Sunscreen","Light jacket","Camera"]','All year','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (11,'bunyonyi-swimming','Swimming & Lakeside Relaxation','fa-person-swimming','The lake has no crocodiles, no hippos and no bilharzia, which makes it the only lake in Uganda where swimming is unequivocally recommended. Most lodges have jetties and swimming areas, and the water sits at a comfortable 22-25°C. Kayaks and SUPs are usually available.','As long as you like','easy',0,15,0,56250,'Free at most lodges; kayak or paddleboard hire USD 5–15 per hour.','All ages with supervision','["Swimwear","Towel","Waterproof sunscreen"]','All year','relaxation',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (11,'bunyonyi-birding','Lakeside Birding Walk','fa-dove','Over 200 species have been recorded around the lake, including the grey crowned crane — Uganda''s national bird — herons, kingfishers, weavers and a good range of sunbirds. Early morning walks along the shoreline and through the terraces with a local guide are the most productive.','2–3 hours','easy',10,25,37500,93750,'USD 10–25 per person with a local bird guide.','All ages','["Binoculars","Field guide","Walking shoes","Fleece for early starts"]','All year; migrants Nov–Mar','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (11,'bunyonyi-village-walk','Terraced Village & Batwa Walk','fa-people-group','Walks through the Bakiga farming villages on the terraced slopes above the lake, covering the extraordinary hillside agriculture, local crafts and daily life, often including a visit to a Batwa community resettled from the nearby forests. Guides are from the villages themselves.','2–4 hours','moderate',15,35,56250,131250,'USD 15–35 per person, paid to the community.','All ages','["Walking shoes","Sun hat","Water","Cash for crafts"]','All year','culture',3);
