INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (12,'ssese-islands','Ssese Islands','Ssese Islands','Eighty-four islands and Uganda''s best beaches',1,'Kalangala','North-western Lake Victoria, reached by ferry from Entebbe or Bukakata',-0.3167,32.2833,'https://sspark.genspark.ai/i/2fIrK9HdsRsc4p3K?width=2560','https://sspark.genspark.ai/i/UAB5lpiWrdJClYlx?width=2560','An archipelago of eighty-four islands in Lake Victoria, with white sand beaches, forested interiors and a pace of life that makes the mainland feel frantic.','The Ssese archipelago is Uganda''s beach destination. **Bugala** is the largest and most developed island, with the district town of Kalangala, a string of beach resorts along its shoreline and most of the visitor infrastructure. The other eighty-three range from inhabited fishing islands to uninhabited scraps of forest.
INSERT INTO destination_categories (destination_id,category_id) VALUES (12,8);
INSERT INTO destination_categories (destination_id,category_id) VALUES (12,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (12,11);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (12,'ssese-beach-time','Beaches & Swimming','fa-umbrella-beach','Bugala''s southern and eastern shores have the best sand, and most resorts have private beach frontage with loungers, hammocks and beach volleyball. Ask your resort where swimming is considered lower-risk for bilharzia, and avoid shallow weedy margins and reed beds.','As long as you like','easy',0,10,0,37500,'Free at resort beaches; day-use fees of USD 3–10 apply at some properties for non-guests.','All ages','["Swimwear","Towel","Sunscreen","Insect repellent for dusk"]','All year','relaxation',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (12,'ssese-fishing','Fishing Trip with Local Fishermen','fa-fish','Going out on the lake in a local boat, usually early morning, targeting Nile perch and tilapia with the fishermen who work these waters daily. Arranged through resorts or directly at the landing sites, and you can normally have your catch cooked for dinner.','3–5 hours','easy',20,60,75000,225000,'USD 20–60 per boat depending on duration and whether tackle is provided.','All ages with supervision','["Sun hat","Sunscreen","Water","Light rain jacket"]','All year; calmer water Jun–Sep and Dec–Feb','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (12,'ssese-forest-walk','Island Forest Walk','fa-leaf','Guided walks into the forested interior of Bugala, with vervet and black-and-white colobus monkeys, good birding and remnant tropical forest. Local guides also cover the island''s history and the Ssese people''s traditional beliefs, in which the islands held significant spiritual importance.','2–3 hours','easy',10,25,37500,93750,'USD 10–25 per person with a local guide.','All ages','["Closed shoes","Insect repellent","Water","Binoculars"]','All year','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (12,'ssese-quad-biking','Quad Biking & Island Tours','fa-motorcycle','Quad bikes and guided tours along the island tracks between beaches, fishing villages and viewpoints. The murram roads and forest sections make for a good half-day, and it is the fastest way to see a lot of Bugala.','1–4 hours','easy',35,90,131250,337500,'USD 35–90 per person depending on duration.','16 and above to drive','["Closed shoes","Sunglasses","Bandana for dust","Long trousers"]','All year; dusty in dry months','adventure',3);
