INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (13,'rwenzori-mountains-national-park','Rwenzori Mountains National Park','Rwenzori Mountains','Glaciers on the equator',3,'Kasese, Bundibugyo & Kabarole','Western Uganda, on the DR Congo border',0.3853,29.8722,'https://sspark.genspark.ai/i/PWZ0pDCOc3WdOIHJ?width=2560','https://sspark.genspark.ai/i/NvJhyCVXHKyEzdJn?width=2560','The Mountains of the Moon — a 996 km² glaciated range rising to 5,109 m at Margherita Peak, Africa''s third-highest summit and the continent''s only permanent ice outside Kilimanjaro and Mount Kenya.','The Rwenzori are not volcanoes. Unlike Kilimanjaro or Elgon they were pushed up as a block of ancient rock along the Albertine Rift, which is why the range is a long jagged wall rather than a cone, and why it holds glaciers on six separate massifs. Ptolemy described "Lunae Montes" feeding the Nile in the second century; the range was not climbed until the Duke of the Abruzzi''s expedition in 1906.
INSERT INTO destination_categories (destination_id,category_id) VALUES (13,4);
INSERT INTO destination_categories (destination_id,category_id) VALUES (13,1);
