INSERT INTO destination_categories (destination_id,category_id) VALUES (13,11);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (13,'margherita-summit','Margherita Peak Summit Trek','fa-mountain','The full expedition to Africa''s third-highest point. Seven to nine days through all five vegetation zones, with a summit day that involves roped glacier travel across the Stanley Plateau using crampons and ice axe. You need prior mountain experience, genuine fitness and tolerance for sustained wet cold. Guides, porters and technical equipment are mandatory and included in operator packages.','7–9 days','expert',1500,2500,5625000,9375000,'USD 1,500–2,500 per person all-inclusive of park fees, guides, porters, huts, meals and technical gear.','18 and above with mountain experience','["Full alpine kit","-10°C sleeping bag","Waterproof everything","Gaiters","Dry bags","Personal first aid"]','Jun–Aug, Dec–Feb only','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (13,'rwenzori-central-circuit','Central Circuit Trek (no summit)','fa-person-hiking','The classic 7-day loop through the Mubuku and Bujuku valleys without the technical summit day. You still reach around 4,300 m at Scott Elliot Pass, see the Bujuku and Kitandara lakes, and walk the full sequence of vegetation zones. Far more achievable than Margherita and arguably the better experience for most trekkers.','6–7 days','challenging',900,1500,3375000,5625000,'USD 900–1,500 per person including park fees, guides, porters and hut accommodation.','16 and above with good fitness','["Waterproof boots","Gaiters","Warm sleeping bag","Rain shell","Trekking poles"]','Jun–Aug, Dec–Feb','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (13,'rwenzori-short-trek','Short Trek to Lake Mahoma or Mutinda','fa-shoe-prints','Three to four day treks reaching the forest, bamboo and heather zones without going high. Lake Mahoma at 2,651 m and the Mutinda viewpoint on the Kilembe route both make excellent shorter objectives, and you sleep in the same mountain huts as the full expeditions. The best option if you want the Rwenzori landscape without an eight-day commitment.','3–4 days','moderate',400,700,1500000,2625000,'USD 400–700 per person including guides, porters, huts and park fees.','12 and above','["Waterproof boots","Gaiters","Rain jacket","Warm layers","Sleeping bag"]','All year, drier Jun–Aug and Dec–Feb','adventure',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (13,'bakonzo-culture','Bakonzo Cultural Trail','fa-drum','Village walks in the Rwenzori foothills with Bakonzo guides, covering traditional blacksmithing, basket weaving, bark cloth, coffee processing and the clan history and mountain beliefs that surround the range. A good acclimatisation day or an alternative if you are not trekking.','3–5 hours','easy',25,50,93750,187500,'USD 25–50 per person, paid to the community association.','All ages','["Walking shoes","Rain jacket","Cash for crafts"]','All year','culture',3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (13,'https://sspark.genspark.ai/i/NvJhyCVXHKyEzdJn?width=2560','Margherita Peak at 5,109 m — Africa''s third-highest summit','Landscape','Licensed imagery',1,0);
