INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (14,'mount-elgon-national-park','Mount Elgon National Park','Mount Elgon','The world''s largest volcanic caldera, and no technical climbing',2,'Mbale, Sironko, Bulambuli, Kapchorwa & Bukwo','Eastern Uganda, on the Kenyan border above Mbale',1.1361,34.5386,'https://sspark.genspark.ai/i/ODqeIhgXfUpm2Din?width=2560','https://sspark.genspark.ai/i/6tA2qRCU5ho5Byfq?width=2560','An extinct volcano with a 40 km-wide caldera — one of the largest intact calderas on earth — and a 4,321 m summit at Wagagai that can be walked without ropes or crampons.','Elgon was once higher than Kilimanjaro. Eruptions ceased around 24 million years ago and erosion has since reduced the cone and opened a vast caldera, roughly 40 km across and 8 km wide in places, ringed by a series of peaks. **Wagagai** at 4,321 m is the highest and sits on the Ugandan side.
INSERT INTO destination_categories (destination_id,category_id) VALUES (14,4);
INSERT INTO destination_categories (destination_id,category_id) VALUES (14,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (14,7);
INSERT INTO destination_categories (destination_id,category_id) VALUES (14,2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (14,'wagagai-summit','Wagagai Summit Trek','fa-mountain-sun','Four to six days to the 4,321 m summit and back, with a night or two inside the caldera. No ropes, crampons or technical skill required — this is sustained uphill walking at altitude. The Sasa route is the quickest at three days up; Piswa is gentler over four. Summit morning is cold and usually starts before dawn to catch clear views east into Kenya.','4–6 days','challenging',450,900,1687500,3375000,'USD 450–900 per person including park fees, mandatory guide, porters and camping. Considerably cheaper than comparable Kilimanjaro routes.','14 and above with good fitness','["Broken-in boots","-5°C sleeping bag","Waterproofs","Insulated layers","Trekking poles","Head torch"]','Jun–Aug, Dec–Mar','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (14,'elgon-caldera-crossing','Caldera Crossing & Hot Springs','fa-hot-tub-person','An extension of the summit trek that descends into the caldera to camp beside the hot springs on its floor, then crosses to exit by a different route. Adds a day or two and takes you through the strangest terrain on the mountain — an enormous flat-bottomed bowl ringed by peaks, with steam venting from the ground.','5–7 days total','challenging',600,1100,2250000,4125000,'USD 600–1,100 per person as part of an extended package.','16 and above','["Full trekking kit","Extra food","Warm sleeping bag","Water purification"]','Jun–Aug, Dec–Mar','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (14,'kapkwai-forest-walk','Kapkwai Forest & Cave Walks','fa-leaf','Day walks from the Forest Exploration Centre at Kapkwai on the lower slopes, taking in caves, Chebonet Falls, the Tutum cave trail and montane forest with colobus and good birding. No altitude, no camping, and an excellent option for families or a single day on the mountain.','3–6 hours','easy',30,60,112500,225000,'USD 30–60 per person including guide and park entry.','All ages','["Walking shoes","Rain jacket","Torch for caves","Water"]','All year','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (14,'bagisu-coffee-trail','Bagisu Coffee & Cultural Trail','fa-mug-hot','The Bagisu have farmed arabica on these slopes for generations. Community trails take you through picking, pulping, drying, roasting and brewing, usually finishing with a cup of what you have just processed, and cover the clan structures and traditions of the area.','3–4 hours','easy',15,35,56250,131250,'USD 15–35 per person, paid to the community group.','All ages','["Walking shoes","Sun hat","Cash for coffee purchases"]','All year; harvest Oct–Feb','culture',3);
