INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (15,'mgahinga-gorilla-national-park','Mgahinga Gorilla National Park','Mgahinga','Three volcanoes, gorillas and golden monkeys',3,'Kisoro','South-western corner of Uganda, at the Rwanda and DR Congo borders',-1.3667,29.6333,'https://sspark.genspark.ai/i/ioGj9EnPg9n99hjr?width=2560','https://sspark.genspark.ai/i/boeNPP0JgPf0K6c9?width=2560','Uganda''s smallest national park at 34 km², covering the northern slopes of three Virunga volcanoes — and the only place in the country to see golden monkeys.','Mgahinga is the Ugandan share of the transboundary Virunga Conservation Area, which continues into Rwanda''s Volcanoes National Park and the DRC''s Virunga. Three dormant volcanoes rise from the park: **Muhabura** at 4,127 m, **Gahinga** at 3,474 m and **Sabyinyo** at 3,669 m, whose summit ridge is the point where Uganda, Rwanda and the DRC meet.
