INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (15,'mgahinga-gorilla-trek','Gorilla Trekking — Nyakagezi Family','fa-hippo','Tracking the park''s single habituated family through bamboo and open montane forest. The going is markedly easier than Bwindi and the setting more open, so photography is often better. Group size is capped at eight and contact time at one hour. The family has been consistently resident in recent years after previously moving across the Rwandan border.','3–6 hours','challenging',800,800,3000000,3000000,'USD 800 per person for foreign non-residents; UGX 300,000 for East African citizens. Often more available at short notice than Bwindi.','15 and above','["Hiking boots","Gloves","Rain jacket","Water","Packed lunch"]','All year; easier Jun–Aug and Dec–Feb','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (15,'golden-monkey-tracking','Golden Monkey Tracking','fa-paw','Golden monkeys are an endangered Albertine Rift endemic found only in the Virunga volcanoes, and Mgahinga is the only place in Uganda where they are habituated. Troops of up to eighty move fast through the bamboo, and the tracking is easy, cheap and consistently successful. A four-hour habituation option is also available.','2–4 hours','moderate',100,140,375000,525000,'USD 100 for standard tracking, USD 140 for the four-hour habituation experience.','12 and above','["Walking shoes","Camera with fast shutter","Rain jacket","Water"]','All year','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (15,'muhabura-climb','Mount Muhabura Climb','fa-mountain','The hardest of the three volcano climbs — 4,127 m, steep and relentless, with a small crater lake at the summit and on a clear day views over all eight Virunga volcanoes and across to the Rwenzori. Eight to nine hours return with a ranger. No technical equipment, but sustained effort.','8–9 hours','expert',80,120,300000,450000,'USD 80–120 per person including ranger guide and park fees.','16 and above with good fitness','["Proper boots","2 litres of water","Packed lunch","Warm layer","Rain shell"]','Jun–Aug, Dec–Feb','adventure',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (15,'sabyinyo-tripoint','Mount Sabyinyo Climb','fa-flag','Sabyinyo means "old man''s teeth", after its jagged eroded summit ridge. The climb involves ladders and some scrambling along the ridge, and the third and highest peak is the exact point where Uganda, Rwanda and the DRC meet — you can stand in three countries simultaneously. Seven to eight hours return.','7–8 hours','challenging',80,120,300000,450000,'USD 80–120 per person including ranger guide.','16 and above','["Boots with good grip","Gloves for ladders","Water","Packed lunch","Windproof layer"]','Jun–Aug, Dec–Feb','adventure',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (15,'batwa-trail-mgahinga','The Batwa Trail','fa-drum','Led by Batwa guides who lived in this forest before 1991, the trail covers hunting and gathering techniques, medicinal plants, fire-making and traditional shelters, and ends inside the Garama Cave — once a Batwa refuge during conflict — with singing in the dark. One of the more substantial cultural experiences in Uganda.','4–5 hours','moderate',80,100,300000,375000,'USD 80–100 per person, a substantial share going to the Batwa community.','10 and above','["Walking shoes","Torch for the cave","Rain jacket","Cash for crafts"]','All year','culture',4);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (15,'https://sspark.genspark.ai/i/ioGj9EnPg9n99hjr?width=2560','Three Virunga volcanoes — Muhabura, Gahinga and Sabyinyo — form the park','Landscape','Licensed imagery',1,0);
