INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (16,'kampala','Kampala','Kampala','Seven hills, a kingdom''s capital and Uganda''s engine room',1,'Kampala','Central Uganda, north of Lake Victoria',0.3476,32.5825,'https://sspark.genspark.ai/i/dgPvwPGArDPe8mgC?width=2560','https://sspark.genspark.ai/i/UEyN3CD9xlMcaZhY?width=2560','Uganda''s capital — dense, loud and built across a series of hills — with the country''s best museums, markets, nightlife and the royal sites of the Buganda kingdom.','Kampala was founded on seven hills and has spread far beyond them. The name comes from *kasozi k''empala*, "hill of the impala", after the antelope the Kabaka once hunted here. Each of the original hills carries an institution: Mengo the Kabaka''s palace, Namirembe the Anglican cathedral, Rubaga the Catholic cathedral, Kasubi the royal tombs, Old Kampala the Gaddafi National Mosque, Nakasero the commercial centre and Makerere the university.
INSERT INTO destination_categories (destination_id,category_id) VALUES (16,9);
INSERT INTO destination_categories (destination_id,category_id) VALUES (16,5);
INSERT INTO destination_categories (destination_id,category_id) VALUES (16,10);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'kampala-city-tour','Guided City & Seven Hills Tour','fa-city','A full-day guided circuit of the city''s key sites — the Gaddafi Mosque with its minaret view, the Uganda Museum, Kasubi Tombs, the Kabaka''s Palace and Owino Market. The sites are spread across the hills and the traffic makes independent navigation slow, so a guide with a vehicle is by far the most efficient way to see them.','Full day, 6–8 hours','easy',40,100,150000,375000,'USD 40–100 per person depending on group size, including transport and guide; site entry fees usually separate.','All ages','["Modest clothing","Walking shoes","Cash for entry fees","Water"]','All year','culture',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'gaddafi-mosque','Gaddafi National Mosque & Minaret','fa-mosque','The largest mosque in East Africa, completed in 2007 and seating 15,000. Guided tours cover the architecture and the building''s history, and the real draw is the climb up the minaret — 304 steps to an unobstructed 360-degree view over the whole city, easily the best vantage point in Kampala.','1–1.5 hours','moderate',8,12,30000,45000,'Around UGX 35,000 per person for non-residents including the guided tour and minaret climb.','All ages; the minaret climb needs reasonable fitness','["Modest dress — shoulders and knees covered","Socks (shoes are removed)","Camera"]','All year; go early for clearer views','culture',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'uganda-museum','Uganda Museum','fa-landmark','Founded in 1908 and the oldest museum in East Africa. The ethnographic collection covers the country''s kingdoms and peoples, and the traditional musical instrument gallery — where you can often play the instruments — is the highlight. There is also a natural history section and an outdoor display of traditional homesteads from different regions.','1.5–2.5 hours','easy',5,10,18750,37500,'Around UGX 20,000 for non-residents; additional small fee for photography.','All ages','["Camera","Cash for entry"]','All year','history',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'kabaka-palace-tour','Kabaka''s Palace & Amin Torture Chambers','fa-landmark-dome','The Buganda king''s palace at Mengo, with the ceremonial approach road, and — beneath it — the underground cells built as an armoury and used by Idi Amin''s regime as a torture and execution site. Guides who take you through the chambers describe what happened there. It is a sobering visit and not suitable for young children.','1–2 hours','easy',8,15,30000,56250,'UGX 20,000-50,000 per person for non-residents including a guide.','14 and above recommended','["Torch","Modest clothing","Cash"]','All year','history',3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'ndere-cultural-performance','Ndere Centre Cultural Performance','fa-drum','The Ndere Troupe performs traditional music and dance from across Uganda — Baganda, Acholi, Karamojong, Bagisu and more — in a purpose-built amphitheatre, with the compere explaining the origin and meaning of each piece. Performances run several evenings a week and dinner is available. The best single introduction to Uganda''s cultural diversity.','3 hours','easy',15,30,56250,112500,'Around UGX 50,000-100,000 per person; dinner extra.','All ages','["Light jacket for the evening","Camera","Cash"]','All year; check the performance schedule','culture',4);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (16,'kampala-food-market-tour','Market & Street Food Tour','fa-utensils','Guided walks through Nakasero and Owino markets taking in produce, spices, crafts and secondhand goods, with stops for rolex — the chapati-and-egg roll that is Uganda''s signature street food — matoke, groundnut sauce and roasted maize. Chaotic, loud and the best way to understand how the city actually works.','3–4 hours','easy',25,60,93750,225000,'USD 25–60 per person including guide and food tastings.','All ages','["Small notes","Bag worn in front","Comfortable shoes","Hand sanitiser"]','All year','culture',5);
