INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (17,'entebbe','Entebbe','Entebbe','Lakeside calm at the country''s front door',1,'Wakiso','Central Uganda, on a Lake Victoria peninsula 40 km south of Kampala',0.0512,32.446,'https://sspark.genspark.ai/i/EezmN3yog2tOHX8V?width=2560','https://sspark.genspark.ai/i/77IeC6aVNovj2nSL?width=2560','Uganda''s airport town and colonial-era capital — quiet, green and on the lake, with botanical gardens, a wildlife centre and beaches within minutes of the terminal.','Entebbe was the administrative capital of the Uganda Protectorate from 1894 until independence in 1962, and it still feels like it: wide tree-lined avenues, low colonial buildings, large gardens and a pace utterly unlike Kampala 40 km up the road. Sitting on a peninsula in Lake Victoria, it is surrounded by water on three sides and has a permanent lake breeze.
