INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (17,'botanical-gardens-birding','Botanical Gardens Birding Walk','fa-dove','Gardens laid out in 1898 running down to the lake shore, with over 200 recorded bird species. Early morning walks with one of the gate guides reliably produce great blue turaco, black-and-white casqued hornbill, orange weaver and the resident fruit bat colony. Flat, shaded and easy walking.','2–3 hours','easy',5,20,18750,75000,'Entry around UGX 10,000-20,000 for non-residents; local bird guide UGX 30,000-60,000.','All ages','["Binoculars","Insect repellent","Sun hat","Water"]','All year; migrants Nov–Mar','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (17,'uwec-visit','Uganda Wildlife Education Centre','fa-paw','A rescue and rehabilitation centre on the lake shore with large naturalistic enclosures holding rhino, lion, leopard, chimpanzee, giraffe and shoebill. Behind-the-scenes tours, a keeper-for-a-day programme and overnight stays are available. The best family activity in the Entebbe area and a reliable way to see a shoebill.','2–4 hours','easy',15,50,56250,187500,'Around USD 15-20 for standard entry; behind-the-scenes and keeper programmes USD 40-100.','All ages','["Camera","Sun hat","Water","Cash"]','All year','family',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (17,'entebbe-lake-sunset','Lake Victoria Sunset & Beaches','fa-umbrella-beach','A string of beaches along the peninsula — Lido, Aero Beach, Imperial — with bars, restaurants and boat hire. Sunset over the lake from the western shore is the main event, and there is usually live music at weekends. Note the bilharzia risk if you plan to swim.','2–4 hours','easy',2,15,7500,56250,'Beach entry UGX 5,000-20,000 at private beaches; boat hire negotiated separately.','All ages','["Insect repellent","Light jacket","Cash"]','All year','relaxation',2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (17,'https://sspark.genspark.ai/i/77IeC6aVNovj2nSL?width=2560','The Botanical Gardens run down to the Lake Victoria shore','Landscape','Licensed imagery',1,0);
