INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (18,'kasubi-tombs','Kasubi Tombs','Kasubi Tombs','The burial ground of the Buganda kings',1,'Kampala','Kasubi Hill, north-western Kampala',0.3306,32.5528,'https://sspark.genspark.ai/i/SbQedXVo0UOG7X5Z?width=2560','https://sspark.genspark.ai/i/zvtNOBspJO41OcH5?width=2560','A UNESCO World Heritage Site on one of Kampala''s hills, where four Kabakas of Buganda are buried beneath the largest thatched structure in the region.','Kasubi is the spiritual centre of the Buganda kingdom. The site was established in 1882 as a palace for Kabaka Muteesa I and converted to a royal burial ground on his death in 1884. Four Kabakas lie here: **Muteesa I**, **Mwanga II**, **Daudi Chwa II** and **Sir Edward Muteesa II**, who was also Uganda''s first president.
INSERT INTO destination_categories (destination_id,category_id) VALUES (18,5);
