INSERT INTO destination_categories (destination_id,category_id) VALUES (18,9);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (18,'kasubi-guided-tour','Guided Tour of the Royal Tombs','fa-landmark-dome','A guided walk through the site covering the construction of Muzibu Azaala Mpanga, the Buganda clan system, the regalia and drums held there, the lives of the four buried Kabakas and the 2010 fire and reconstruction. Guides are usually clan members with direct connection to the site.','1–1.5 hours','easy',8,15,30000,56250,'UGX 20,000-50,000 per person for non-residents, guide included.','All ages','["Modest clothing","Socks","Cash","Camera for exteriors only"]','All year','culture',0);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (18,'https://sspark.genspark.ai/i/SbQedXVo0UOG7X5Z?width=2560','Muzibu Azaala Mpanga, the main tomb building at Kasubi','Culture','Licensed imagery',1,0);
