INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (18,'https://sspark.genspark.ai/i/x2tVlTmmEoLd1BC4?width=2560','A UNESCO World Heritage Site since 2001','Culture','Licensed imagery',0,2);
