INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (19,'uganda-wildlife-education-centre','Uganda Wildlife Education Centre','UWEC Entebbe','Rescued wildlife on the shore of Lake Victoria',1,'Wakiso','Entebbe, on the Lake Victoria shoreline',0.0553,32.4786,'https://sspark.genspark.ai/i/opnpyKjgymiBPBLH?width=2560','https://sspark.genspark.ai/i/Q97G0YOlEPyXwNKK?width=2560','A conservation and rescue centre in Entebbe holding rhino, lion, leopard, chimpanzee and shoebill in large lakeside enclosures — and the easiest place in Uganda to see the country''s wildlife in a day.','Founded in 1952 as the Entebbe Zoo and substantially reformed in the 1990s, UWEC is now a rescue, rehabilitation and conservation education facility rather than a conventional zoo. Its residents are animals confiscated from the illegal wildlife trade, orphaned, or injured and unable to return to the wild, and the enclosures are large, naturalistic and set in forest running down to the lake.
INSERT INTO destination_categories (destination_id,category_id) VALUES (19,6);
INSERT INTO destination_categories (destination_id,category_id) VALUES (19,9);
INSERT INTO destination_categories (destination_id,category_id) VALUES (19,12);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (19,'uwec-general-entry','Self-Guided Visit','fa-paw','Walking the centre''s trails through forest and lakeside enclosures at your own pace, taking in the rhino, big cats, chimpanzees, giraffe and the shoebill. Interpretive signage is good and keepers are happy to talk. Two to three hours covers it comfortably.','2–3 hours','easy',15,20,56250,75000,'Around USD 15-20 for foreign non-residents; significantly less for East African citizens and children.','All ages','["Camera","Sun hat","Water","Comfortable shoes"]','All year','family',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (19,'uwec-behind-scenes','Behind-the-Scenes Tour','fa-key','A guided tour into the areas closed to general visitors — the animal kitchen, veterinary clinic, quarantine facilities and night houses — with keepers explaining diet preparation, medical care and the rescue and rehabilitation process for confiscated animals.','1.5–2 hours','easy',40,70,150000,262500,'USD 40–70 per person in addition to entry; book in advance.','8 and above','["Closed shoes","Camera","Hand sanitiser"]','All year','family',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (19,'uwec-keeper-for-a-day','Keeper for a Day','fa-bucket','A full day working alongside UWEC keepers — preparing food, cleaning enclosures, delivering enrichment and assisting with feeds across several sections. Physical, hands-on and by far the most memorable thing available here, particularly for teenagers and animal-minded adults.','Full day, 7–8 hours','moderate',100,180,375000,675000,'USD 100–180 per person including lunch; must be booked well in advance.','12 and above','["Old clothes","Closed sturdy shoes","Hat","Change of clothes"]','All year','family',2);
