INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (20,'ngamba-island','Ngamba Island Chimpanzee Sanctuary','Ngamba Island','Fifty rescued chimpanzees on a forested island',1,'Mukono','Lake Victoria, 23 km south-east of Entebbe',-0.0989,32.6467,'https://sspark.genspark.ai/i/PhFB7j8Mp2WByr8p?width=2560','https://sspark.genspark.ai/i/1hgV4cMD3fRSiR2I?width=2560','A 100-acre forested island in Lake Victoria where around fifty rescued chimpanzees live largely free — reached by a boat trip from Entebbe and one of the best conservation visits in East Africa.','Ngamba was established in 1998 by the Chimpanzee Sanctuary and Wildlife Conservation Trust to house chimpanzees orphaned by the bushmeat and pet trades, animals that cannot be returned to the wild because they lack the skills or because no safe habitat is available. Around fifty live here now.
INSERT INTO destination_categories (destination_id,category_id) VALUES (20,6);
INSERT INTO destination_categories (destination_id,category_id) VALUES (20,8);
INSERT INTO destination_categories (destination_id,category_id) VALUES (20,3);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (20,'ngamba-feeding-visit','Feeding-Time Visit','fa-hippo','The standard day trip: boat transfer from Entebbe, arrival for one of the two daily supplementary feeds, and viewing from the raised walkway as the whole community comes in from the forest. Caregivers narrate the group''s social dynamics and individual histories. Usually includes lunch on the island.','Half day, 4–6 hours including transfers','easy',130,180,487500,675000,'USD 130–180 per person including return boat, sanctuary fees and lunch; speedboat costs more than canoe.','All ages','["Sun hat","Sunscreen","Camera","Rain jacket"]','All year','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (20,'ngamba-caregiver','Caregiver for a Day','fa-hand-holding-heart','A full day working with the sanctuary caregivers: preparing and distributing food, assisting with health monitoring, preparing enrichment and observing behaviour alongside staff. Numbers are strictly limited and health screening applies.','Full day','moderate',250,400,937500,1500000,'USD 250–400 per person including transfers and meals; book well in advance.','16 and above','["Old clothes","Closed shoes","Hat","Proof of vaccinations if requested"]','All year','wildlife',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (20,'ngamba-overnight','Overnight on the Island','fa-campground','Tented accommodation on the island with the evening and early morning to yourself once the day visitors leave. You see the chimps settle for the night and the morning release into the forest, and the lake at dawn is exceptional.','Overnight, 24 hours','easy',200,350,750000,1312500,'USD 200–350 per person including transfers, full board and all sanctuary activities.','All ages','["Insect repellent","Torch","Warm layer","Swimwear"]','All year','wildlife',2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (20,'https://sspark.genspark.ai/i/1hgV4cMD3fRSiR2I?width=2560','Around 50 rescued chimpanzees live on the 100-acre island','Wildlife','Licensed imagery',1,0);
