INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (20,'https://sspark.genspark.ai/i/Wq7xpJNhskLCD8al?width=2560','Overnight tented accommodation is available','Accommodation','Licensed imagery',0,7);
INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (21,'mabamba-swamp','Mabamba Swamp','Mabamba Swamp','The most reliable shoebill site on earth',1,'Wakiso','Lake Victoria wetland, west of Entebbe',0.0833,32.3167,'https://sspark.genspark.ai/i/WNTP5qOtr5406Dlp?width=2560','https://sspark.genspark.ai/i/2UvZmbOpBl2jFbJ4?width=2560','A 16,500-hectare papyrus wetland on the northern shore of Lake Victoria, and the single best place in the world to see a shoebill from a dugout canoe.','Mabamba Bay is a Ramsar-listed wetland of narrow papyrus channels opening into Lake Victoria, and it has become internationally known for one bird. The **shoebill** — a metre and a half tall, prehistoric-looking, with a bill like a clog — is difficult to see anywhere. At Mabamba the local guides know the resident birds'' habitual channels and fishing spots, and the success rate on a morning trip runs well above 80%.
INSERT INTO destination_categories (destination_id,category_id) VALUES (21,12);
INSERT INTO destination_categories (destination_id,category_id) VALUES (21,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (21,6);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (21,'mabamba-shoebill-canoe','Shoebill Canoe Trip','fa-dove','A two to three hour trip in a motorised dugout through the papyrus channels with a community guide, searching for the resident shoebills. Engines are cut to approach quietly. Alongside the shoebill you should get papyrus gonolek, jacanas, kingfishers, herons and a long supporting list. Dawn departures are substantially more productive.','2–3 hours','easy',30,50,112500,187500,'USD 30–50 per person for canoe and guide through the community association; full packages from Entebbe USD 80–150 including transfers.','All ages; life jackets provided','["Binoculars","Long lens","Dry bag","Sun hat","Sunscreen","Water"]','All year; best Dec–Mar and always at dawn','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (21,'mabamba-community-walk','Wetland Community Walk','fa-people-group','A guided walk around the landing site and the villages that depend on the swamp, covering fishing, papyrus harvesting, the pressures of rice farming and sand mining on the wetland, and the conservation work of the eco-tourism association. Good context for what you have just seen on the water.','1–2 hours','easy',10,25,37500,93750,'USD 10–25 per person, paid to the community association.','All ages','["Walking shoes","Sun hat","Cash","Water"]','All year','culture',1);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (21,'https://sspark.genspark.ai/i/2UvZmbOpBl2jFbJ4?width=2560','The shoebill — Mabamba is the most reliable site in the world to see one','Wildlife','Licensed imagery',1,0);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (21,'https://sspark.genspark.ai/i/WNTP5qOtr5406Dlp?width=2560','Papyrus channels are navigated in a motorised dugout','Activities','Licensed imagery',0,1);
