INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (21,'https://sspark.genspark.ai/i/w8Mqoymfj5kUdXhU?width=2560','Boat trips leave at first light, when shoebills are most active','Activities','Licensed imagery',0,3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (21,'https://sspark.genspark.ai/i/xUeW5pOn0TVmrX0r?width=2560','Around 300 bird species use the swamp','Wildlife','Licensed imagery',0,4);
