INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (22,'fort-portal','Fort Portal','Fort Portal','Crater lakes, tea estates and the Mountains of the Moon',3,'Kabarole','Western Uganda, below the northern Rwenzori',0.671,30.275,'https://sspark.genspark.ai/i/J5ZHUP14cItLgtwc?width=2560','https://sspark.genspark.ai/i/K73HSJLunKdhNDSF?width=2560','A green highland town ringed by around thirty explosion craters, tea estates and the Rwenzori foothills — Uganda''s designated Tourism City and the hub of the western circuit.','Fort Portal sits at 1,500 m in some of the most attractive country in Uganda, and it functions as the base for an unusually dense cluster of attractions. The town itself is small, walkable and pleasant, with a growing cafe scene and the Karambi royal tombs of the Tooro kingdom nearby. The **Tooro Palace** on the hill above town is the seat of one of Uganda''s traditional kingdoms.
INSERT INTO destination_categories (destination_id,category_id) VALUES (22,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (22,9);
INSERT INTO destination_categories (destination_id,category_id) VALUES (22,4);
INSERT INTO destination_categories (destination_id,category_id) VALUES (22,5);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (22,'crater-lakes-walk','Crater Lakes Walk','fa-person-hiking','Walking routes through the Ndali-Kasenda crater field linking Lake Nkuruba, Lake Nyinambuga, Lake Lyantonde and the viewpoints between them. Paths run along crater rims and through smallholder farmland with the Rwenzori on the horizon on clear days. Routes range from an hour to a full day.','2–8 hours','moderate',5,20,18750,75000,'Free to walk; local guide UGX 20,000-40,000 per group, recommended for access and route-finding.','All ages depending on route','["Walking shoes","Rain jacket","Water","Sun hat","Camera"]','All year; firmer paths Jun–Aug and Dec–Feb','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (22,'tea-estate-tour','Tea Estate Tour','fa-mug-hot','Tours of the large tea estates around Fort Portal covering plucking, withering, rolling, oxidation and drying, usually finishing with a tasting. The plantations themselves — geometric green terraces running over the hills — are among the most photographed landscapes in Uganda.','2–3 hours','easy',10,25,37500,93750,'USD 10–25 per person depending on the estate and whether tasting is included.','All ages','["Sun hat","Walking shoes","Camera","Cash for tea purchases"]','All year','culture',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (22,'amabere-caves','Amabere ga Nyina Mwiru Caves','fa-mountain','Caves behind a small waterfall with stalactites that, according to Tooro legend, are the breasts of Nyina Mwiru, a princess mutilated by her father. Guides tell the story and explain the site''s role in Tooro tradition. Short, cheap and a good hour combined with the crater lake walks nearby.','1–2 hours','easy',3,8,11250,30000,'Around UGX 10,000-20,000 per person including a guide.','All ages','["Closed shoes","Torch","Rain jacket","Cash"]','All year','culture',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (22,'fort-portal-cycling','Crater Lakes Cycling','fa-bicycle','Mountain biking on the tracks between the craters, through tea estates and villages. Bikes are hired in town or at the crater lodges, and the terrain is hilly but manageable. The best way to cover the crater field in a day.','3–6 hours','moderate',15,45,56250,168750,'USD 15–45 per person including bike hire; guided rides cost more.','14 and above','["Closed shoes","Sun protection","Water","Rain jacket"]','Dry months preferred for traction','adventure',3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (22,'https://sspark.genspark.ai/i/J5ZHUP14cItLgtwc?width=2560','The Ndali-Kasenda crater field holds around thirty explosion craters','Landscape','Licensed imagery',1,0);
