INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (23,'semuliki-national-park','Semuliki National Park','Semuliki','Congo Basin rainforest and boiling hot springs',3,'Bundibugyo','Western Uganda, in the Albertine Rift at the DR Congo border',0.8333,30.1333,'https://sspark.genspark.ai/i/s2JRNJBii0dlwrmF?width=2560','https://sspark.genspark.ai/i/xnk3D9PzXt5aC3e1?width=2560','The only tract of true Congo Basin lowland rainforest in East Africa, holding bird species found nowhere else in the region — and a pair of hot springs that jet water at close to boiling point.','Semuliki is biologically distinct from everything else in Uganda. At 220 km² it is small, and at 670-760 m it is low — this is an eastern extension of the Ituri forest of the Congo Basin, and the species composition reflects that. For birders it is one of the most significant sites in Africa: around 440 recorded species, including roughly 40 Guinea-Congo biome specialities that occur nowhere else in East Africa. Names like Nkulengu rail, lyre-tailed honeyguide, Congo serpent eagle and white-crested hornbill are the reason specialists make the journey.
INSERT INTO destination_categories (destination_id,category_id) VALUES (23,1);
INSERT INTO destination_categories (destination_id,category_id) VALUES (23,11);
