INSERT INTO destination_categories (destination_id,category_id) VALUES (23,6);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (23,'sempaya-hot-springs','Sempaya Hot Springs Walk','fa-hot-tub-person','A boardwalk through forest to the two springs. Bitente, the male spring, jets water about two metres into the air; Nyasimbi, the female, is a wide boiling pool sending steam through the trees. Guides explain the Bamba traditions attached to both and will boil eggs or plantain in the water for you. Water is close to 100°C — stay on the walkways.','1.5–3 hours','easy',20,35,75000,131250,'USD 20–35 per person with ranger guide, in addition to park entry.','All ages with close supervision','["Closed shoes","Insect repellent","Water","Camera"]','All year','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (23,'kirumia-birding-trail','Kirumia Birding Trail','fa-dove','A 13 km trail through lowland forest to the Semliki river, and the main route for the park''s Guinea-Congo biome specialities. A full day out with a specialist guide, targeting species that occur nowhere else in East Africa. Flat but long, hot and humid, and often muddy.','Full day, 6–8 hours','moderate',50,120,187500,450000,'USD 50–120 per group for a specialist bird guide, plus park entry.','14 and above','["Binoculars","Bird guide","3 litres of water","Packed lunch","Insect repellent"]','Dec–Feb and Jun–Aug when passable','nature',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (23,'semuliki-red-monkey-trail','Red Monkey Trail','fa-leaf','A shorter forest walk along the park''s eastern edge, named for the Central African red colobus found here. Also good for grey-cheeked mangabey, forest birds and occasionally forest elephant sign. A manageable half-day alternative to the Kirumia trail.','3–4 hours','moderate',30,50,112500,187500,'USD 30–50 per person including ranger guide.','12 and above','["Closed shoes","Long sleeves","Insect repellent","Water"]','Dry months preferred','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (23,'semuliki-batwa-culture','Batwa & Bamba Cultural Visit','fa-drum','Visits to Batwa and Bamba communities near the park covering forest knowledge, traditional medicine, hunting techniques, music and dance. The Batwa here were displaced from the Semuliki forest, and the visits are organised through community groups with fees going directly to them.','2–3 hours','easy',20,50,75000,187500,'USD 20–50 per person, paid to the community.','All ages','["Walking shoes","Cash for crafts","Ask before photographing"]','All year','culture',3);
