INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (24,'ziwa-rhino-sanctuary','Ziwa Rhino Sanctuary','Ziwa Rhino Sanctuary','The only wild rhinos in Uganda, tracked on foot',4,'Nakasongola','Central-northern Uganda, on the Kampala–Gulu highway',1.6167,32.15,'https://sspark.genspark.ai/i/6EC98lx7vHNtHHLL?width=2560','https://sspark.genspark.ai/i/X3DPV7SA6dpdiN43?width=2560','A 70 km² sanctuary holding the only rhinoceros population in Uganda, where you track southern white rhino on foot with a ranger — and it sits directly on the road to Murchison Falls.','Uganda''s rhinos were wiped out by poaching and civil conflict, with the last confirmed wild individual recorded in 1983. Ziwa was established in 2005 by the Rhino Fund Uganda to reintroduce the species, starting with six founder animals from Kenya and the United States — one of them donated by Disney''s Animal Kingdom. Breeding has been steady and the population has grown substantially since, with a long-term aim of restocking Uganda''s national parks.
INSERT INTO destination_categories (destination_id,category_id) VALUES (24,6);
INSERT INTO destination_categories (destination_id,category_id) VALUES (24,12);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (24,'rhino-tracking','Rhino Tracking on Foot','fa-hippo','Rangers locate a rhino group, drive you to the nearest access point and then walk you in, usually approaching to twenty or thirty metres. Sessions run through the day and typically take one to two hours depending on where the animals are. The rangers monitoring each group know the individuals and their histories.','1–2 hours','easy',50,50,187500,187500,'Around USD 50 per person for foreign non-residents; lower for East African citizens and children.','All ages; children must stay with adults at all times','["Closed shoes","Neutral colours","Sun hat","Camera","Water"]','All year','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (24,'ziwa-shoebill-canoe','Shoebill Canoe Trip','fa-dove','A dawn canoe trip into the Lugogo swamp within the sanctuary, targeting the resident shoebills along with a long list of other wetland birds. Quieter and far less visited than Mabamba, and a good option if you are staying overnight.','2–3 hours','easy',30,50,112500,187500,'USD 30–50 per person including canoe and guide.','All ages','["Binoculars","Sun hat","Dry bag","Water"]','All year; best at dawn','nature',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (24,'ziwa-night-walk','Night Nature Walk','fa-moon','A guided walk after dark with torches, looking for nocturnal species — bushbabies, genets, civets, nightjars, owls and the occasional porcupine. Only available to overnight guests.','1.5–2 hours','easy',20,35,75000,131250,'USD 20–35 per person with a ranger guide.','8 and above','["Closed shoes","Torch","Long sleeves","Insect repellent"]','All year','nature',2);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (24,'https://sspark.genspark.ai/i/X3DPV7SA6dpdiN43?width=2560','Southern white rhino at Ziwa — the only wild rhinos in Uganda','Wildlife','Licensed imagery',1,0);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (24,'https://sspark.genspark.ai/i/6EC98lx7vHNtHHLL?width=2560','Rhinos are tracked on foot with an armed ranger','Activities','Licensed imagery',0,1);
