INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (25,'mabira-forest','Mabira Forest','Mabira Forest','Rainforest, ziplines and a canopy walk an hour from Kampala',1,'Buikwe','Central Uganda, straddling the Kampala–Jinja highway',0.4167,33,'https://sspark.genspark.ai/i/UEMveIfJx0UO02rM?width=2560','https://sspark.genspark.ai/i/rALu1YHxHrB7CyR9?width=2560','A 306 km² block of rainforest cut through by the main road east, with a canopy walkway, ziplines and good primate viewing — the easiest forest experience to reach from Kampala.','Mabira is one of the largest surviving natural forests in central Uganda and, because the Kampala-Jinja highway runs straight through it, by far the most accessible. Gazetted in 1932, it has survived repeated attempts to clear portions for sugarcane — proposals in 2007 and 2011 triggered substantial public protest, and the forest became a rallying point for Ugandan environmental activism.
INSERT INTO destination_categories (destination_id,category_id) VALUES (25,11);
