INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (25,'mabira-ziplining','Canopy Ziplining','fa-person-falling-burst','A course of zipline runs through and above the forest canopy, the longest around 250 m, operated from the Griffin Falls area with full harness, helmet and instruction. No experience needed and the whole course takes about two hours. The best-value adrenaline activity within reach of Kampala.','1.5–2.5 hours','easy',25,40,93750,150000,'USD 25–40 per person including all equipment and guides.','10 and above; weight limits apply','["Closed shoes","Long trousers","Tie back long hair"]','All year','adventure',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (25,'mabira-canopy-walk','Canopy Walkway','fa-bridge','A suspended walkway roughly 30 m above the forest floor, giving eye-level access to the canopy where most of the forest''s birds and primates actually live. Guided, and much better early in the morning when the canopy is active.','1–2 hours','easy',10,20,37500,75000,'USD 10–20 per person including guide.','6 and above','["Binoculars","Camera","Closed shoes"]','All year; best early morning','nature',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (25,'mabira-nature-walk','Guided Forest Nature Walk','fa-leaf','Walks on marked trails with a forest guide, covering the tree species, medicinal plant uses, butterflies and the forest''s primates — with a reasonable chance of Uganda mangabey, red-tailed monkey and colobus. Routes range from an hour to a half-day to Griffin Falls.','1–4 hours','easy',10,25,37500,93750,'USD 10–25 per person with a guide, depending on trail length.','All ages','["Closed shoes","Insect repellent","Binoculars","Water"]','All year','nature',2);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (25,'mabira-mountain-biking','Forest Mountain Biking','fa-bicycle','Mountain bike trails on the forest tracks and through the surrounding tea and village areas, with bikes hired on site. Around 20 km of rideable track, mostly flat and shaded, suitable for reasonably fit beginners.','2–4 hours','moderate',15,40,56250,150000,'USD 15–40 per person including bike hire and guide.','12 and above','["Closed shoes","Water","Insect repellent","Rain jacket"]','Drier months for better traction','adventure',3);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (25,'https://sspark.genspark.ai/i/rALu1YHxHrB7CyR9?width=2560','The canopy walkway sits about 30 m above the forest floor','Activities','Licensed imagery',1,0);
