INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (25,'https://sspark.genspark.ai/i/6NQ23cd4LUk8HAFd?width=2560','Home to the endangered Uganda mangabey','Wildlife','Licensed imagery',0,5);
