INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (26,'katonga-wildlife-reserve','Katonga Wildlife Reserve','Katonga','Canoe trails and sitatunga in a quiet river wetland',3,'Kamwenge & Ibanda','Western Uganda, along the Katonga River',0.1,30.75,'https://sspark.genspark.ai/i/PGpV7S0oACsKGEzO?width=2560','https://sspark.genspark.ai/i/smj263J03FU6oGOW?width=2560','A small, rarely visited reserve on the Katonga River where the activities are canoe trails and guided walks rather than game drives — and one of the few places in Uganda to see sitatunga.','Katonga covers 211 km² of riverine wetland, papyrus swamp, woodland and savanna along the Katonga River, which flows between Lake George and Lake Victoria. It was gazetted as a game reserve in 1964 and became a wildlife reserve in 1998, and it receives a tiny fraction of the visitors the national parks see.
INSERT INTO destination_categories (destination_id,category_id) VALUES (26,6);
INSERT INTO destination_categories (destination_id,category_id) VALUES (26,3);
INSERT INTO destination_categories (destination_id,category_id) VALUES (26,12);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (26,'katonga-canoe-trail','Katonga Canoe Trail','fa-sailboat','A guided canoe trip along the Katonga River and into the papyrus channels, the reserve''s signature activity and the best chance of sitatunga, otter and papyrus birds. Quiet, slow and completely different from any national park activity.','2–4 hours','easy',25,45,93750,168750,'USD 25–45 per person including canoe and ranger guide.','10 and above','["Sun hat","Insect repellent","Binoculars","Dry bag","Water"]','Jun–Aug, Dec–Feb','nature',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (26,'katonga-walking-trails','Guided Walking Trails','fa-shoe-prints','Three marked trails through woodland, savanna and riverine habitat with a ranger, taking in bushbuck, waterbuck, colobus and the reserve''s birdlife. Ranges from two to five hours depending on the route chosen.','2–5 hours','moderate',20,40,75000,150000,'USD 20–40 per person with an armed ranger.','12 and above','["Closed shoes","Long trousers","Water","Insect repellent"]','Dry months only','adventure',1);
INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (26,'https://sspark.genspark.ai/i/PGpV7S0oACsKGEzO?width=2560','Wetland and woodland along the Katonga River','Landscape','Licensed imagery',1,0);
