INSERT INTO gallery_images (destination_id,url,caption,category,credit,featured,sort) VALUES (26,'https://sspark.genspark.ai/i/qf9qyK5mRHrEWCAd?width=2560','Riverine habitat, Katonga','Landscape','Licensed imagery',0,3);
INSERT INTO destinations (id,slug,name,short_name,tagline,region_id,district,location_label,latitude,longitude,hero_image,card_image,intro,overview,why_visit,getting_there,travel_advice,highlights,wildlife,what_to_pack,nearby,best_time,best_time_detail,climate_note,distance_from_kampala_km,drive_hours_min,drive_hours_max,cost_from_ugx,entry_fee_foreign_usd,entry_fee_eastafrican_ugx,entry_fee_note,experience_tags,budget_level,budget_levels,recommended_days,duration_band,difficulty,popularity,featured,seo_title,seo_description,og_image) VALUES (27,'pian-upe-wildlife-reserve','Pian Upe Wildlife Reserve','Pian Upe','Uganda''s second-largest protected area, and its emptiest',2,'Nakapiripirit, Amudat & Bukedea','North-eastern Uganda, in Karamoja below Mount Kadam',1.7,34.4167,'https://sspark.genspark.ai/i/Cg8pww9JECTBBYCE?width=2560','https://sspark.genspark.ai/i/GbnUkektoQ2A6Hp4?width=2560','A 2,788 km² sweep of semi-arid Karamoja savanna — the second-largest protected area in Uganda, holding cheetah, roan antelope and ostrich, and visited by almost no one.','Pian Upe is enormous and empty. It takes its name from the Pian, a Karamojong subgroup, and *upe*, the Kalenjin word for enemies, reflecting the contested history of this frontier. The landscape is open short-grass savanna and semi-desert scrub punctuated by rocky inselbergs, with **Mount Kadam** rising to 3,068 m on the eastern boundary and the Napak volcano to the north-west.
