INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (27,'pian-upe-game-drive','Game Drive','fa-binoculars','Ranger-guided drives across the open plains looking for cheetah, roan, kudu, eland and ostrich. Distances are large and sightings sparse, so allow a full morning or afternoon. A 4x4 with good clearance is essential and fuel consumption is significant.','4–6 hours','moderate',25,50,93750,187500,'Ranger guide USD 25–50 per vehicle; you must provide the vehicle.','All ages','["4 litres of water","Sun protection","Binoculars","Dust protection","Packed food"]','Dec–Mar','wildlife',0);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (27,'pian-upe-walking-safari','Walking Safari','fa-shoe-prints','Guided walks with an armed ranger across the short-grass plains and up to the inselbergs. Walking is the best way to experience the emptiness here, and the rangers read tracks and explain the Karamojong relationship with the land. Early morning starts to avoid the heat.','2–4 hours','moderate',20,40,75000,150000,'USD 20–40 per person with an armed ranger.','14 and above','["Closed walking boots","Hat","3 litres of water","Neutral clothing"]','Dec–Mar, early morning','adventure',1);
INSERT INTO activities (destination_id,slug,name,icon,description,duration,difficulty,cost_usd_min,cost_usd_max,cost_ugx_min,cost_ugx_max,cost_note,recommended_age,what_to_bring,best_season,experience_tag,sort) VALUES (27,'pian-upe-karamojong-visit','Karamojong Cultural Visit','fa-drum','Visits to Pian and Karamojong homesteads around the reserve, covering pastoralist life, cattle culture, the manyatta layout, beadwork and traditional dance. Karamoja is Uganda''s most marginalised region and these visits channel income directly to the communities.','2–4 hours','easy',25,60,93750,225000,'USD 25–60 per group, paid to the community.','All ages','["Respectful clothing","Cash for crafts","Ask before photographing","Water"]','All year','culture',2);
