INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (1,1,9,'kampala-to-jinja',80,1.5,2,'tarmac','Fully tarmac on the main eastern highway. Traffic leaving Kampala is the main variable — leave before 07:00 or after 10:00 to avoid an extra hour. The road passes through Mabira Forest at Najjembe, a worthwhile stop.','["Kampala","Mukono","Lugazi","Njeru","Jinja"]','["Kampala","Gayaza","Kayunga","Njeru","Jinja"]',95,'The northern route via Kayunga avoids the worst of the Mukono-Lugazi traffic but is longer and partly murram.',0,'Fully tarmac on the main eastern highway. Traffic leaving Kampala is the main variable — leave before 07:00 or after 10:00 to avoid an extra hour. The road passes through Mabira Forest at Najjembe, a worthwhile stop.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (2,1,2,'kampala-to-entebbe',40,0.75,1.5,'tarmac','The Entebbe Expressway is a toll road and much faster than the old route, typically 45 minutes against 90 in traffic. The old Entebbe Road via Kajjansi is free and passes the craft markets.','["Kampala","Kajjansi","Entebbe"]','["Kampala","Expressway","Entebbe"]',36,'Expressway toll route — fastest option, toll payable by vehicle class.',0,'The Entebbe Expressway is a toll road and much faster than the old route, typically 45 minutes against 90 in traffic. The old Entebbe Road via Kajjansi is free and passes the craft markets.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (3,1,11,'kampala-to-mbale',245,4,4.5,'tarmac','Good tarmac the whole way on the main eastern corridor. Buses run continuously from Kampala and the journey is straightforward. Watch for heavy truck traffic between Jinja and Iganga.','["Kampala","Jinja","Iganga","Bugiri","Mbale"]',NULL,NULL,NULL,0,'Good tarmac the whole way on the main eastern corridor. Buses run continuously from Kampala and the journey is straightforward. Watch for heavy truck traffic between Jinja and Iganga.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (4,1,13,'kampala-to-sipi',277,5,6,'tarmac','Tarmac to Mbale then 65 km north-east through Sironko towards Kapchorwa, now largely paved. On public transport you change at Mbale for a Kapchorwa-bound minibus.','["Kampala","Jinja","Iganga","Mbale","Sironko","Sipi"]',NULL,NULL,NULL,1,'Tarmac to Mbale then 65 km north-east through Sironko towards Kapchorwa, now largely paved. On public transport you change at Mbale for a Kapchorwa-bound minibus.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (5,11,13,'mbale-to-sipi',65,1.5,2,'tarmac','A steady climb from Mbale onto the Elgon escarpment. Minibuses run frequently from Mbale to Kapchorwa and pass through Sipi trading centre.','["Mbale","Sironko","Chema","Sipi"]',NULL,NULL,NULL,0,'A steady climb from Mbale onto the Elgon escarpment. Minibuses run frequently from Mbale to Kapchorwa and pass through Sipi trading centre.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (6,1,28,'kampala-to-masindi',214,3.5,4,'tarmac','Good tarmac on the Gulu highway as far as Kafu, then west to Masindi. Ziwa Rhino Sanctuary sits directly on this route at Nakitoma.','["Kampala","Luweero","Nakasongola","Kafu","Masindi"]',NULL,NULL,NULL,0,'Good tarmac on the Gulu highway as far as Kafu, then west to Masindi. Ziwa Rhino Sanctuary sits directly on this route at Nakitoma.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (7,1,33,'kampala-to-paraa',305,5,6,'mixed','Tarmac to Masindi then park roads to Paraa. The southern Kichumbanyobo gate route passes through Budongo Forest. For the northern bank you continue via Karuma, adding about an hour.','["Kampala","Luweero","Nakasongola","Masindi","Kichumbanyobo Gate","Paraa"]','["Kampala","Luweero","Karuma","Chobe Gate","Paraa"]',345,'The Karuma route approaches from the north bank and avoids the Paraa ferry if your lodge is on that side.',1,'Tarmac to Masindi then park roads to Paraa. The southern Kichumbanyobo gate route passes through Budongo Forest. For the northern bank you continue via Karuma, adding about an hour.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (8,1,41,'kampala-to-ziwa',176,2.5,3,'tarmac','Straightforward tarmac on the Gulu highway. The sanctuary entrance is signposted at Nakitoma. Almost every Murchison itinerary stops here.','["Kampala","Luweero","Nakasongola","Nakitoma"]',NULL,NULL,NULL,0,'Straightforward tarmac on the Gulu highway. The sanctuary entrance is signposted at Nakitoma. Almost every Murchison itinerary stops here.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (9,1,18,'kampala-to-mbarara',266,4,5,'tarmac','The main western highway, tarmac throughout and generally in good condition. The Equator crossing at Kayabwe is the standard photo stop, about 72 km from Kampala.','["Kampala","Mpigi","Masaka","Lyantonde","Mbarara"]',NULL,NULL,NULL,0,'The main western highway, tarmac throughout and generally in good condition. The Equator crossing at Kayabwe is the standard photo stop, about 72 km from Kampala.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (10,1,39,'kampala-to-nshara',228,3.5,4,'mixed','Tarmac to Sanga trading centre, then 13 km of murram to the gate. Any Mbarara-bound bus will drop you at Sanga. Usually passable in a 2WD in dry weather.','["Kampala","Masaka","Lyantonde","Sanga","Nshara Gate"]',NULL,NULL,NULL,0,'Tarmac to Sanga trading centre, then 13 km of murram to the gate. Any Mbarara-bound bus will drop you at Sanga. Usually passable in a 2WD in dry weather.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (11,1,37,'kampala-to-katunguru',410,6,7,'tarmac','Tarmac the whole way via Mbarara. The public road runs through the park itself, so you pass through the boundary at Katunguru. An alternative via Fort Portal is slightly longer but more scenic.','["Kampala","Masaka","Mbarara","Bushenyi","Katunguru"]','["Kampala","Mityana","Mubende","Fort Portal","Kasese","Katunguru"]',420,'The Fort Portal route is marginally longer but passes Kibale and the crater lakes, making it far better as a touring route.',0,'Tarmac the whole way via Mbarara. The public road runs through the park itself, so you pass through the boundary at Katunguru. An alternative via Fort Portal is slightly longer but more scenic.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (12,1,35,'kampala-to-buhoma',510,8,10,'mixed','Tarmac as far as Rukungiri or Kanungu, then murram into Buhoma. A 4x4 is strongly recommended for the final section. Most visitors break the journey at Mbarara or Lake Mburo rather than driving it in one day.','["Kampala","Masaka","Mbarara","Rukungiri","Kanungu","Buhoma"]','["Kampala","Masaka","Mbarara","Kabale","Kanungu","Buhoma"]',530,'Via Kabale — longer but allows a stop at Lake Bunyonyi on the way.',1,'Tarmac as far as Rukungiri or Kanungu, then murram into Buhoma. A 4x4 is strongly recommended for the final section. Most visitors break the journey at Mbarara or Lake Mburo rather than driving it in one day.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (13,1,36,'kampala-to-rushaga',495,8,9.5,'mixed','Tarmac to Kabale then murram into the Rushaga sector. Rushaga and Nkuringo are served from Kabale or Kisoro rather than from Kanungu, which is why the sector on your permit matters so much.','["Kampala","Masaka","Mbarara","Kabale","Rushaga"]',NULL,NULL,NULL,1,'Tarmac to Kabale then murram into the Rushaga sector. Rushaga and Nkuringo are served from Kabale or Kisoro rather than from Kanungu, which is why the sector on your permit matters so much.','curated');
INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (14,1,19,'kampala-to-kabale',411,7,8,'tarmac','Tarmac throughout on the main road to the Rwanda border. A long but straightforward drive; buses run all day and overnight.','["Kampala","Masaka","Mbarara","Ntungamo","Kabale"]',NULL,NULL,NULL,0,'Tarmac throughout on the main road to the Rwanda border. A long but straightforward drive; buses run all day and overnight.','curated');
