INSERT INTO transport_routes (id,from_place_id,to_place_id,slug,distance_km,duration_hours_min,duration_hours_max,road_quality,route_description,waypoints,alt_waypoints,alt_distance_km,alt_note,transfers,notes,data_confidence) VALUES (18,1,21,'kampala-to-fort-portal',320,4.5,5.5,'tarmac','One of the better long drives in Uganda — good tarmac, moderate traffic and attractive country once past Mubende. Buses run frequently.','["Kampala","Mityana","Mubende","Kyenjojo","Fort Portal"]',NULL,NULL,NULL,0,'One of the better long drives in Uganda — good tarmac, moderate traffic and attractive country once past Mubende. Buses run frequently.','curated');
