INSERT INTO itineraries (id,slug,title,subtitle,days,theme,region_focus,summary,hero_image,total_distance_km,cost_ugx_min,cost_ugx_max,best_for,tips,featured) VALUES (1,'jinja-nile-weekend','Jinja & the Nile Weekend','Rafting, the source of the Nile and Mabira Forest in two days',2,'adventure','eastern','The classic Kampala escape. Leave early on Saturday, stop in Mabira Forest, spend the afternoon at the Source of the Nile and give Sunday to the rapids.','https://sspark.genspark.ai/i/0gBJt3LP2OUMPQRY?width=2560',160,650000,1400000,'["Adventure seekers","Short on time","Groups of friends"]','["Leave Kampala before 07:00 to beat traffic","Book rafting a few days ahead in peak season","Bring a change of clothes and reef shoes"]',1);
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (1,1,'Kampala to Jinja via Mabira',7,'Mabira Forest & Source of the Nile','Drive east on the Jinja highway, stopping in Mabira Forest at Najjembe for a short forest walk or zipline. Continue to Jinja for lunch and an afternoon boat trip to the Source of the Nile.','[]','["Mabira forest walk","Source of the Nile boat trip","Sunset on the river"]','Minibus or private car',80,'Riverside lodge near Bujagali','Try a rolex from a Jinja roadside stall.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (1,2,'White-water rafting',9,'Nile rapids','A full day on the Nile with grade 3-5 rapids, lunch on an island, and a late-afternoon return to Kampala.','[]','["Full-day rafting","Swimming in calm stretches"]','Operator transfer, then minibus to Kampala',80,'—','Rafting operators provide all safety equipment.');
INSERT INTO itineraries (id,slug,title,subtitle,days,theme,region_focus,summary,hero_image,total_distance_km,cost_ugx_min,cost_ugx_max,best_for,tips,featured) VALUES (2,'murchison-3-day-safari','Murchison Falls 3-Day Safari','Rhinos, the world''s most powerful waterfall and a Nile game drive',3,'wildlife','northern','The best short safari from Kampala. Track white rhino on foot at Ziwa, then combine a morning game drive with an afternoon boat trip to the base of the falls.','https://sspark.genspark.ai/i/8kBhnQ3GVBeWIMh8?width=2560',670,1500000,4200000,'["First safari","Families","Photographers"]','["Do the launch trip in the afternoon, game drive at dawn","Hike to the top of the falls from the boat jetty","Wear light colours — tsetse flies like dark blue"]',1);
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (2,1,'Kampala to Ziwa and Murchison',24,'Ziwa Rhino Sanctuary','Drive north on the Gulu highway to Ziwa for rhino tracking on foot, then continue to Masindi and into the park, arriving at the top of the falls in the late afternoon.','[]','["Rhino tracking on foot","Top of the falls viewpoint"]','Private 4x4',305,'Lodge near Paraa','Ziwa rhino tracking takes 1-2 hours.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (2,2,'Game drive and Nile launch',2,'Buligi circuit & Victoria Nile','Early ferry across the Nile for a morning game drive on the Buligi circuit — giraffe, elephant, buffalo, lion. After lunch, a three-hour launch trip upstream to the base of the falls.','[]','["Morning game drive","Launch trip to the falls"]','Private 4x4 + Paraa ferry',60,'Lodge near Paraa','Bring a telephoto lens for the launch trip.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (2,3,'Budongo chimps and return',2,'Budongo Forest','Optional early chimpanzee tracking in Kaniyo Pabidi before the drive back to Kampala.','[]','["Chimpanzee tracking"]','Private 4x4',305,'—','Chimp permits sell out — book ahead.');
INSERT INTO itineraries (id,slug,title,subtitle,days,theme,region_focus,summary,hero_image,total_distance_km,cost_ugx_min,cost_ugx_max,best_for,tips,featured) VALUES (3,'gorillas-and-savanna-7-days','Gorillas, Chimps & Savanna — 7 Days','The south-west circuit: Kibale, Queen Elizabeth, Bwindi and Lake Bunyonyi',7,'wildlife','western','Uganda''s signature week. Chimpanzees in Kibale, tree-climbing lions and the Kazinga Channel in Queen Elizabeth, mountain gorillas in Bwindi and a lazy last day on Lake Bunyonyi.','https://sspark.genspark.ai/i/I4JvByiZFsBH6sa5?width=2560',1205,7500000,22000000,'["Wildlife lovers","Once-in-a-lifetime trips","Photographers"]','["Buy the gorilla permit first — everything else follows","A 4x4 with driver-guide is the easiest option","Pack for rain in every month"]',1);
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,1,'Kampala to Fort Portal',22,'Fort Portal crater lakes','Drive west via Mubende to Fort Portal. Afternoon walk around the crater lakes.','[]','["Crater lakes walk"]','Private 4x4',320,'Crater lake lodge','Stop for lunch in Mubende.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,2,'Chimpanzee tracking in Kibale',5,'Kibale Forest','Morning chimp tracking from Kanyanchu. Afternoon Bigodi Wetland walk for primates and birds.','[]','["Chimpanzee tracking","Bigodi wetland walk"]','Private 4x4',36,'Crater lake lodge','Morning tracking has the most activity.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,3,'To Queen Elizabeth',3,'Kazinga Channel','Drive south to Queen Elizabeth. Afternoon launch on the Kazinga Channel for hippo, buffalo, elephant and birds.','[]','["Kazinga Channel launch"]','Private 4x4',130,'Lodge near Mweya','Sit on the shore side of the boat.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,4,'Game drive and Ishasha',3,'Kasenyi & Ishasha','Dawn game drive on the Kasenyi plains, then south through Ishasha to look for tree-climbing lions, arriving in Buhoma by evening.','[]','["Kasenyi game drive","Ishasha tree-climbing lions"]','Private 4x4',160,'Lodge in Buhoma','The Ishasha road is rough after rain.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,5,'Gorilla trekking',1,'Bwindi — Buhoma sector','Briefing at 07:30 then trek to your assigned gorilla family for one hour. Afternoon Buhoma community walk.','[]','["Gorilla trekking","Community walk"]','On foot',0,'Lodge in Buhoma','Hire a porter — it matters.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,6,'To Lake Bunyonyi',11,'Lake Bunyonyi','Scenic drive to Lake Bunyonyi. Afternoon canoe among the islands.','[]','["Dugout canoe","Island visit"]','Private 4x4',140,'Island or lakeside lodge','Swimming is bilharzia-free here.');
INSERT INTO itinerary_days (itinerary_id,day_number,title,destination_id,destination_label,description,schedule,activities,transport,distance_km,accommodation,tip) VALUES (3,7,'Return to Kampala',NULL,'Kabale to Kampala','Long drive back to Kampala with a stop at the Equator.','[]','["Equator stop"]','Private 4x4',419,'—','Or fly from Kisoro to save a day.');
